DO $absent$ BEGIN IF to_regprocedure('public.fn_ca_assign_tournament_player_seat_locked(uuid,uuid,uuid,integer)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_ca_assign_tournament_player_seat_locked(uuid,uuid,uuid,integer)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_ca_assign_tournament_player_seat_locked(p_tournament_id uuid, p_user_id uuid, p_table_id uuid, p_seat_number integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_tp public.tournament_players%ROWTYPE;
  v_table public.tables%ROWTYPE;
  v_live public.table_seats%ROWTYPE;
  v_destination public.table_seats%ROWTYPE;
  v_live_count integer;
  v_stack numeric;
  v_felt_stack numeric;
  v_live_total numeric;
  v_own_live numeric;
  v_cap_chips numeric;
  v_cap integer;
  v_seat_id uuid;
  v_current_players integer;
  v_rows integer;
  v_assigned_at timestamptz;
  v_expected_club_id uuid;
  v_expected_horse_id uuid;
  -- Fresh tournament-seat defaults. A rebuy that keeps its live chair keeps
  -- its own persisted bank; only a newly inserted/revived occupant starts the
  -- same 30-second/four-use state as a physical INSERT.
  v_time_bank_uses integer:=4;
  v_time_bank_seconds integer:=30;
  v_previous_money_path text:=current_setting('app.money_path',true);
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_table_id IS NULL
     OR p_seat_number IS NULL OR p_seat_number NOT BETWEEN 1 AND 10 THEN
    RAISE EXCEPTION 'tournament, player, table and legal seat are required'
      USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF upper(COALESCE(v_t.status::text,'')) NOT IN ('REGISTERING','RUNNING') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_not_assignable',
      'status',upper(COALESCE(v_t.status::text,'')));
  END IF;
  v_cap:=public.fn_ca_tournament_seat_cap(p_tournament_id);

  -- Lock the beneficiary and every roster row claiming the requested
  -- coordinate before any table/seat row. This matches terminal settlement's
  -- tournament -> roster -> tables -> seats child order.
  PERFORM tp.id
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND (tp.user_id=p_user_id
       OR (tp.table_id=p_table_id AND tp.seat_number=p_seat_number))
   ORDER BY tp.id
   FOR UPDATE;

  SELECT * INTO v_tp FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_registered');
  END IF;
  IF v_tp.status::text NOT IN ('registered','playing') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','player_not_assignable','status',v_tp.status::text);
  END IF;

  IF v_tp.status::text='registered' THEN
    v_stack:=COALESCE(v_t.starting_chips,0)
             +GREATEST(COALESCE(v_tp.chips,0),0);
  ELSE
    /* THE FELT IS THE BANK ON A MOVE (2026-09-10). This took the new
       seat's stack from tournament_players.chips, a MIRROR, rather than
       from the seat the player is leaving. In the ordinary case the two
       agree - measured 1,540 of 1,541 live tournament seats. When they
       do not, this statement silently minted or destroyed the gap.
       Night Owl Special b84f312f: the engine's own hands show 256,000 +
       128,000 = 384,000 at 18:01, exactly the 48 x 8,000 bought in; a
       move at 22:34:25 wrote 448,000 over a felt of 256,000 and the
       tournament has held 64,000 chips nobody bought ever since.
       The seat is where the engine settles every hand, so the seat is
       the witness; the mirror is a projection. Read the felt first and
       fall back to the mirror only when the player holds no live seat. */
    SELECT ts.stack INTO v_felt_stack
      FROM public.table_seats ts
      JOIN public.tables tb ON tb.id=ts.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND ts.user_id=p_user_id
       AND ts.left_at IS NULL
     ORDER BY ts.joined_at DESC, ts.id
     LIMIT 1;
    v_stack:=COALESCE(v_felt_stack,COALESCE(v_tp.chips,0));
  END IF;

  /* A SEAT ASSIGNMENT NEVER MINTS TOURNAMENT CHIPS (2026-09-10).
     Whatever corrupts an input, this gate makes the class impossible:
     an assignment may move chips between chairs but may never RAISE the
     tournament's live total above what was bought in. A normal move
     cannot trip it - the player's own live seat is subtracted before
     v_stack is added back, so the total is unchanged. It fires only when
     seating a player would ADD chips beyond the cap. An existing overage
     is tolerated (history) and refused only from growing (the future),
     the same shape as this estate's NOT VALID constraints. */
  IF v_tp.status::text<>'registered' THEN
    SELECT COALESCE(sum(ts.stack),0) INTO v_live_total
      FROM public.table_seats ts JOIN public.tables tb ON tb.id=ts.table_id
     WHERE tb.tournament_id=p_tournament_id AND ts.left_at IS NULL;
    SELECT COALESCE(sum(ts.stack),0) INTO v_own_live
      FROM public.table_seats ts JOIN public.tables tb ON tb.id=ts.table_id
     WHERE tb.tournament_id=p_tournament_id AND ts.user_id=p_user_id
       AND ts.left_at IS NULL;
    SELECT (count(*)*COALESCE(v_t.starting_chips,0))
           +(COALESCE(sum(tp2.rebuys),0)*COALESCE(v_t.rebuy_chips,0))
           +(count(*) FILTER (WHERE tp2.add_on)*COALESCE(v_t.addon_chips,0))
      INTO v_cap_chips
      FROM public.tournament_players tp2
     WHERE tp2.tournament_id=p_tournament_id;
    IF (v_live_total-v_own_live+v_stack)>v_live_total
       AND (v_live_total-v_own_live+v_stack)>v_cap_chips THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','tournament_chip_conservation',
        'live_total',v_live_total,'own_live',v_own_live,
        'proposed_stack',v_stack,'bought_in_cap',v_cap_chips);
    END IF;
  END IF;
  IF v_stack::text IN ('NaN','Infinity','-Infinity')
     OR v_stack<=0 OR v_stack<>trunc(v_stack)
     OR v_stack>2147483647 THEN
    RETURN jsonb_build_object('ok',false,'reason','player_stack_invalid');
  END IF;

  SELECT * INTO v_table FROM public.tables tb
   WHERE tb.id=p_table_id
   FOR UPDATE;
  IF NOT FOUND OR v_table.tournament_id IS DISTINCT FROM p_tournament_id THEN
    RETURN jsonb_build_object('ok',false,'reason','table_tournament_mismatch');
  END IF;
  IF lower(COALESCE(v_table.status::text,'')) NOT IN
       ('waiting','running','active')
     OR COALESCE(v_table.is_deleted,false)
     OR p_seat_number>LEAST(
          v_cap,GREATEST(2,COALESCE(NULLIF(v_table.max_players,0),v_cap))) THEN
    RETURN jsonb_build_object('ok',false,'reason','table_not_assignable');
  END IF;

  -- A physical row is reusable, but none of its former occupant's identity or
  -- per-session state is. Resolve every derived value while the tournament,
  -- roster and table rows are locked, then write the same complete shape for a
  -- new row and a revived row. Passing the old club_id through the seat stamp
  -- trigger would make it the preferred club and could attribute this entry to
  -- the departed occupant.
  v_expected_club_id:=public.fn_seat_club_for_user(
    p_user_id,p_table_id,v_tp.club_id);
  SELECT CASE WHEN COALESCE(p.is_horse,false) THEN p.id ELSE NULL END
    INTO v_expected_horse_id
    FROM public.profiles p
   WHERE p.id=p_user_id;

  PERFORM s.id
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL
   ORDER BY s.id
   FOR UPDATE OF s;
  SELECT count(*)::integer INTO v_live_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL;
  IF v_live_count>1 THEN
    RAISE EXCEPTION 'tournament player already owns multiple live seats'
      USING ERRCODE='P0404';
  END IF;
  IF v_live_count=1 THEN
    SELECT s.* INTO v_live
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL
     FOR UPDATE OF s;
    IF v_live.table_id IS DISTINCT FROM p_table_id
       OR v_live.seat_number IS DISTINCT FROM p_seat_number THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','player_already_seated_elsewhere',
        'table_id',v_live.table_id,'seat_number',v_live.seat_number);
    END IF;
    SELECT count(*)::integer INTO v_current_players
      FROM public.table_seats s
     WHERE s.table_id=p_table_id AND s.left_at IS NULL;
    IF v_live.stack IS DISTINCT FROM v_stack
       OR v_tp.status::text<>'playing'
       OR v_tp.chips IS DISTINCT FROM v_stack::integer
       OR v_tp.table_id IS DISTINCT FROM p_table_id
       OR v_tp.seat_number IS DISTINCT FROM p_seat_number
       OR v_table.current_players IS DISTINCT FROM v_current_players
       OR v_live.joined_at IS NULL THEN
      RAISE EXCEPTION 'existing tournament assignment is not an exact receipt'
        USING ERRCODE='P0404';
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'replayed',true,'tournament_id',p_tournament_id,
      'user_id',p_user_id,'table_id',p_table_id,
      'seat_id',v_live.id,'seat_number',p_seat_number,'stack',v_stack,
      'current_players',v_current_players,'assigned_at',v_live.joined_at);
  END IF;

  SELECT * INTO v_destination FROM public.table_seats s
   WHERE s.table_id=p_table_id AND s.seat_number=p_seat_number
   FOR UPDATE;
  IF FOUND AND v_destination.left_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','seat_taken');
  END IF;

  -- A departed occupant can still carry a stale roster coordinate. Correct
  -- that link inside this assignment transaction; never overwrite a live
  -- seat or leave two active roster rows claiming one chair.
  UPDATE public.tournament_players tp
     SET table_id=NULL,seat_number=NULL
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id<>p_user_id
     AND tp.table_id=p_table_id AND tp.seat_number=p_seat_number;

  v_assigned_at:=clock_timestamp();
  PERFORM set_config(
    'app.money_path','fn_assign_tournament_player_seat_atomic',true);
  BEGIN
    IF v_destination.id IS NULL THEN
      INSERT INTO public.table_seats(
        table_id,user_id,player_id,member_id,seat_number,stack,status,
        joined_at,left_at,is_sitting_out,is_away,leave_pending,
        scheduled_leave_hands,horse_id,auto_rebuy,time_bank_remaining,
        time_bank_uses_remaining,club_id,sit_out_at,entry_hold,
        entry_post_agreed)
      VALUES(
        p_table_id,p_user_id,NULL,NULL,p_seat_number,v_stack,'active',
        v_assigned_at,NULL,false,false,false,NULL,v_expected_horse_id,false,
        v_time_bank_seconds,v_time_bank_uses,v_expected_club_id,NULL,NULL,
        false)
      RETURNING id INTO v_seat_id;
    ELSE
      UPDATE public.table_seats s
         SET user_id=p_user_id,player_id=NULL,member_id=NULL,stack=v_stack,
             status='active',joined_at=v_assigned_at,left_at=NULL,
             is_sitting_out=false,is_away=false,leave_pending=false,
             sit_out_at=NULL,scheduled_leave_hands=NULL,
             horse_id=v_expected_horse_id,entry_hold=NULL,
             entry_post_agreed=false,auto_rebuy=false,
             time_bank_remaining=v_time_bank_seconds,
             time_bank_uses_remaining=v_time_bank_uses,
             club_id=v_expected_club_id
       WHERE s.id=v_destination.id AND s.left_at IS NOT NULL
       RETURNING id INTO v_seat_id;
      IF v_seat_id IS NULL THEN
        RAISE EXCEPTION 'vacated tournament seat changed during assignment'
          USING ERRCODE='40001';
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config(
      'app.money_path',COALESCE(v_previous_money_path,''),true);
    RAISE;
  END;
  PERFORM set_config(
    'app.money_path',COALESCE(v_previous_money_path,''),true);

  UPDATE public.tournament_players tp
     SET status='playing',chips=v_stack::integer,
         table_id=p_table_id,seat_number=p_seat_number
   WHERE tp.id=v_tp.id AND tp.status::text IN ('registered','playing');
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament roster changed during seat assignment'
      USING ERRCODE='40001';
  END IF;

  SELECT count(*)::integer INTO v_current_players
    FROM public.table_seats s
   WHERE s.table_id=p_table_id AND s.left_at IS NULL;
  UPDATE public.tables tb
     SET current_players=v_current_players,updated_at=now()
   WHERE tb.id=p_table_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'tournament table vanished during seat assignment'
      USING ERRCODE='40001';
  END IF;

  IF (SELECT count(*) FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL)<>1
     OR NOT EXISTS(
       SELECT 1 FROM public.table_seats s
        WHERE s.id=v_seat_id AND s.table_id=p_table_id
          AND s.user_id=p_user_id AND s.seat_number=p_seat_number
          AND s.left_at IS NULL AND s.stack=v_stack
          AND s.player_id IS NULL AND s.member_id IS NULL
          AND s.horse_id IS NOT DISTINCT FROM v_expected_horse_id
          AND s.club_id IS NOT DISTINCT FROM v_expected_club_id
          AND s.time_bank_remaining=v_time_bank_seconds
          AND s.time_bank_uses_remaining=v_time_bank_uses
          AND NOT COALESCE(s.is_sitting_out,false)
          AND NOT COALESCE(s.is_away,false)
          AND NOT COALESCE(s.leave_pending,false)
          AND NOT COALESCE(s.auto_rebuy,false)
          AND s.sit_out_at IS NULL
          AND s.scheduled_leave_hands IS NULL
          AND s.entry_hold IS NULL
          AND NOT s.entry_post_agreed)
     OR NOT EXISTS(
       SELECT 1 FROM public.tournament_players tp
        WHERE tp.id=v_tp.id AND tp.status::text='playing'
          AND tp.chips=v_stack::integer AND tp.table_id=p_table_id
          AND tp.seat_number=p_seat_number)
     OR NOT EXISTS(
       SELECT 1 FROM public.tables tb
        WHERE tb.id=p_table_id AND tb.tournament_id=p_tournament_id
          AND tb.current_players=v_current_players) THEN
    RAISE EXCEPTION 'atomic tournament seat assignment final proof is not exact'
      USING ERRCODE='P0404';
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'replayed',false,'tournament_id',p_tournament_id,
    'user_id',p_user_id,'table_id',p_table_id,'seat_id',v_seat_id,
    'seat_number',p_seat_number,'stack',v_stack,
    'current_players',v_current_players,'assigned_at',v_assigned_at);
END;
$function$;
ALTER FUNCTION public.fn_ca_assign_tournament_player_seat_locked(uuid,uuid,uuid,integer) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_ca_assign_tournament_player_seat_locked(uuid,uuid,uuid,integer) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_ca_assign_tournament_player_seat_locked(uuid,uuid,uuid,integer) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_ca_choose_tournament_seat_locked(uuid,uuid,uuid,integer)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_ca_choose_tournament_seat_locked(uuid,uuid,uuid,integer)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_ca_choose_tournament_seat_locked(p_tournament_id uuid, p_user_id uuid, p_preferred_table_id uuid DEFAULT NULL::uuid, p_preferred_seat_number integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_capacity jsonb;
  v_table_id uuid;
  v_tournament_cap integer;
  v_cap integer;
  v_seat_number integer;
  v_seat_id uuid;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'tournament and player are required for seat selection'
      USING ERRCODE='22023';
  END IF;

  v_capacity:=public.fn_ensure_late_registration_capacity(
    p_tournament_id,0);
  IF COALESCE((v_capacity->>'ok')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'tournament capacity could not be established: %',
      COALESCE(v_capacity->>'reason','unknown') USING ERRCODE='55000';
  END IF;
  v_tournament_cap:=public.fn_ca_tournament_seat_cap(p_tournament_id);

  SELECT tb.id,
         LEAST(v_tournament_cap,
               GREATEST(2,COALESCE(NULLIF(tb.max_players,0),v_tournament_cap)))
    INTO v_table_id,v_cap
    FROM public.tables tb
   WHERE tb.tournament_id=p_tournament_id
     AND lower(COALESCE(tb.status,'')) IN ('running','waiting','active')
     AND NOT COALESCE(tb.is_deleted,false)
     AND EXISTS (
       SELECT 1
         FROM generate_series(
           1,LEAST(v_tournament_cap,
             GREATEST(2,COALESCE(NULLIF(tb.max_players,0),v_tournament_cap))))
           AS legal(seat_number)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.table_seats occupied
           WHERE occupied.table_id=tb.id
             AND occupied.seat_number=legal.seat_number
             AND occupied.left_at IS NULL))
   ORDER BY (
       SELECT count(*)
         FROM generate_series(
           1,LEAST(v_tournament_cap,
             GREATEST(2,COALESCE(NULLIF(tb.max_players,0),v_tournament_cap))))
           AS legal(seat_number)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.table_seats occupied
           WHERE occupied.table_id=tb.id
             AND occupied.seat_number=legal.seat_number
             AND occupied.left_at IS NULL)) DESC,
     (tb.id=p_preferred_table_id) DESC,
     tb.created_at,tb.id
   LIMIT 1
   FOR UPDATE OF tb;
  IF v_table_id IS NULL THEN
    RAISE EXCEPTION
      'TOURNAMENT_SEAT_CAPACITY_UNAVAILABLE: no legal chair exists for tournament %',
      p_tournament_id USING ERRCODE='55000';
  END IF;

  IF v_table_id=p_preferred_table_id
     AND p_preferred_seat_number BETWEEN 1 AND v_cap
     AND NOT EXISTS (
       SELECT 1 FROM public.table_seats occupied
        WHERE occupied.table_id=v_table_id
          AND occupied.seat_number=p_preferred_seat_number
          AND occupied.left_at IS NULL) THEN
    v_seat_number:=p_preferred_seat_number;
  ELSE
    SELECT legal.seat_number INTO v_seat_number
      FROM generate_series(1,v_cap) AS legal(seat_number)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.table_seats occupied
        WHERE occupied.table_id=v_table_id
          AND occupied.seat_number=legal.seat_number
          AND occupied.left_at IS NULL)
     ORDER BY legal.seat_number
     LIMIT 1;
  END IF;
  IF v_seat_number IS NULL THEN
    RAISE EXCEPTION 'chosen tournament table lost its legal chair'
      USING ERRCODE='40001';
  END IF;

  SELECT s.id INTO v_seat_id
    FROM public.table_seats s
   WHERE s.table_id=v_table_id AND s.seat_number=v_seat_number
   FOR UPDATE;

  RETURN jsonb_build_object(
    'ok',true,'tournament_id',p_tournament_id,'user_id',p_user_id,
    'table_id',v_table_id,'seat_number',v_seat_number,
    'physical_seat_id',v_seat_id,'capacity',v_capacity);
END;
$function$;
ALTER FUNCTION public.fn_ca_choose_tournament_seat_locked(uuid,uuid,uuid,integer) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_ca_choose_tournament_seat_locked(uuid,uuid,uuid,integer) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_ca_choose_tournament_seat_locked(uuid,uuid,uuid,integer) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_ca_latest_committed_knockout_candidate(uuid,uuid)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_ca_latest_committed_knockout_candidate(uuid,uuid)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_ca_latest_committed_knockout_candidate(p_tournament_id uuid, p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_table_id uuid;
  v_hand_number bigint;
  v_candidate_id uuid;
  v_candidate_hand_id uuid;
  v_settlement_hand_id uuid;
  v_settlement_hand_text text;
  v_atomic_stack text;
  v_settlement_stack text;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'tournament and player are required for knockout evidence'
      USING ERRCODE='22023';
  END IF;

  SELECT c.id,c.table_id,c.hand_number,c.hand_id
    INTO v_candidate_id,v_table_id,v_hand_number,v_candidate_hand_id
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
     AND c.stack_after=0
   ORDER BY c.hand_number DESC,c.id DESC
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION
      'REBUY_KNOCKOUT_CANDIDATE_REQUIRED: no zero-stack generation names this player'
      USING ERRCODE='55000';
  END IF;

  SELECT a.stack_result->>'hand_id',
         a.stack_result->'written'->>p_user_id::text
    INTO v_settlement_hand_text,v_atomic_stack
    FROM public.hand_atomic_commits a
   WHERE a.table_id=v_table_id
     AND a.hand_number=v_hand_number
     AND a.hand_id=v_candidate_hand_id;
  -- fn_ca_settle_hand_stacks_absolute derives this id from md5(... )::uuid.
  -- PostgreSQL UUIDs are canonical hexadecimal but that deterministic hash is
  -- not required to carry RFC version/variant nibbles.
  IF NOT FOUND
     OR COALESCE(v_settlement_hand_text,'')
          !~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR COALESCE(v_atomic_stack,'')!~'^-?[0-9]+([.][0-9]+)?$' THEN
    RAISE EXCEPTION
      'REBUY_ATOMIC_HAND_REQUIRED: candidate is not the exact accepted zero hand'
      USING ERRCODE='P0404';
  END IF;
  IF v_atomic_stack::numeric<>0 THEN
    RAISE EXCEPTION
      'REBUY_ATOMIC_HAND_REQUIRED: candidate hand did not commit a zero stack'
      USING ERRCODE='P0404';
  END IF;
  v_settlement_hand_id:=v_settlement_hand_text::uuid;

  SELECT k.result->'written'->>p_user_id::text
    INTO v_settlement_stack
    FROM public.settlement_idempotency_keys k
   WHERE k.table_id=v_table_id
     AND k.hand_id=v_settlement_hand_id
     AND k.status='succeeded'
     AND k.completed_at IS NOT NULL
     AND k.result->>'table_id'=v_table_id::text
     AND COALESCE(k.result->>'hand_number','')~'^[0-9]+$'
     AND (k.result->>'hand_number')::bigint=v_hand_number;
  IF NOT FOUND
     OR COALESCE(v_settlement_stack,'')!~'^-?[0-9]+([.][0-9]+)?$' THEN
    RAISE EXCEPTION
      'REBUY_SETTLEMENT_RECEIPT_REQUIRED: atomic zero hand has no exact successful settlement'
      USING ERRCODE='P0404';
  END IF;
  IF v_settlement_stack::numeric<>0 THEN
    RAISE EXCEPTION
      'REBUY_SETTLEMENT_RECEIPT_REQUIRED: exact settlement did not commit a zero stack'
      USING ERRCODE='P0404';
  END IF;

  RETURN v_candidate_id;
END;
$function$;
ALTER FUNCTION public.fn_ca_latest_committed_knockout_candidate(uuid,uuid) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_ca_latest_committed_knockout_candidate(uuid,uuid) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_ca_latest_committed_knockout_candidate(uuid,uuid) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_ca_process_tournament_chip_purchase_money_v1(uuid,uuid,text,numeric,numeric,integer,text)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_ca_process_tournament_chip_purchase_money_v1(uuid,uuid,text,numeric,numeric,integer,text)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_ca_process_tournament_chip_purchase_money_v1(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer, p_client_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_t record;
  v_p record;
  v_unit integer := public.fn_ca_tournament_unit_cents(p_tournament_id);  -- DIAMOND PHASE 8
  v_dia jsonb;                                                              -- DIAMOND PHASE 8
  v_balance numeric;
  v_ratio numeric;
  v_is_bounty boolean;
  v_bounty_head numeric;
  v_base numeric;
  v_fee numeric;
  v_total numeric;
  v_add integer;
  v_new_chips integer;
  v_seat record;
  v_key text;
  v_inserted integer;
  v_cat text;
  v_club uuid;
  v_stack_after numeric;
  v_expected numeric;
  v_fee_ratio numeric;
  v_was_seated boolean:=false;
  v_rows integer;
  v_led_cat text;
  v_led_cp text;
  v_led_ent text;
  v_led_tid text;
BEGIN
  IF NOT (COALESCE(auth.role(),'service_role')='service_role')
     AND (auth.uid() IS NULL OR auth.uid()<>p_user_id) THEN
    RAISE EXCEPTION
      'process_tournament_rebuy: caller may only transact for themselves'
      USING ERRCODE='42501';
  END IF;
  IF p_rebuy_type NOT IN ('rebuy','reentry','addon') THEN
    RAISE EXCEPTION 'Invalid rebuy type: %',p_rebuy_type
      USING ERRCODE='22023';
  END IF;
  IF p_client_token IS NULL OR length(btrim(p_client_token))=0
     OR length(btrim(p_client_token))>128 THEN
    RAISE EXCEPTION 'exact tournament chip-purchase token is required'
      USING ERRCODE='22023';
  END IF;

  SELECT id,name,club_id,status,buy_in_amount,buy_in_fee,starting_chips,
         is_rebuy,is_reentry,add_on_available,addon_period_triggered,
         rebuy_cost,rebuy_chips,rebuy_levels,late_reg_levels,max_rebuys,
         max_reentries,addon_cost,addon_chips,addon_levels,current_level,
         prize_pool,is_bounty,is_pko,is_mystery_bounty,bounty_amount
    INTO v_t
    FROM public.tournaments
   WHERE id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002';
  END IF;
  IF v_t.status NOT IN ('RUNNING','REGISTERING','ANNOUNCED') THEN
    RAISE EXCEPTION 'Tournament is not accepting chip purchases (status %)',v_t.status;
  END IF;

  SELECT id,chips,status,prize,rebuys,add_on,table_id,club_id
    INTO v_p
    FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Player not registered in this tournament';
  END IF;
  IF v_p.status='eliminated' AND COALESCE(v_p.prize,0)>0 THEN
    RAISE EXCEPTION
      'Finishing Place Already Paid - A Rebuy Cannot Resurrect A Settled Result';
  END IF;
  v_club:=v_p.club_id;
  IF v_club IS NULL THEN
    RAISE EXCEPTION
      'Tournament entry funding club is missing; refusing a substituted wallet'
      USING ERRCODE='P0404';
  END IF;

  v_cat:=CASE WHEN p_rebuy_type='addon' THEN 'addon' ELSE 'rebuy' END;
  v_key:=CASE WHEN p_rebuy_type='addon'
    THEN 'tourney:'||p_tournament_id::text||':addon:'||p_user_id::text
    ELSE 'tourney:'||p_tournament_id::text||':'||p_rebuy_type||':'||
         p_user_id::text||':tok:'||btrim(p_client_token)
  END;

  IF p_rebuy_type='addon' THEN
    PERFORM 1
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE s.user_id=p_user_id AND s.left_at IS NULL
       AND tb.tournament_id=p_tournament_id
     LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'No Live Seat For This % - Aborting So No Charge Is Made',p_rebuy_type;
    END IF;
    IF NOT COALESCE(v_t.add_on_available,false) THEN
      RAISE EXCEPTION 'Add-ons are not offered in this tournament';
    END IF;
    IF COALESCE(v_p.add_on,false) THEN
      RAISE EXCEPTION 'Add-on already taken';
    END IF;
    v_base:=COALESCE(NULLIF(v_t.addon_cost,0),v_t.buy_in_amount,0);
    v_add:=COALESCE(NULLIF(v_t.addon_chips,0),v_t.starting_chips,0)::integer;
  ELSE
    IF p_rebuy_type='rebuy' AND NOT COALESCE(v_t.is_rebuy,false) THEN
      RAISE EXCEPTION 'Rebuys are not offered in this tournament';
    END IF;
    IF p_rebuy_type='reentry' AND NOT COALESCE(v_t.is_reentry,false) THEN
      RAISE EXCEPTION 'Re-entries are not offered in this tournament';
    END IF;
    IF p_rebuy_type='rebuy' AND v_t.max_rebuys IS NOT NULL
       AND COALESCE(v_p.rebuys,0)>=v_t.max_rebuys THEN
      RAISE EXCEPTION 'Rebuy limit reached (% of %)',v_p.rebuys,v_t.max_rebuys;
    END IF;
    IF p_rebuy_type='reentry' AND v_t.max_reentries IS NOT NULL
       AND COALESCE(v_p.rebuys,0)>=v_t.max_reentries THEN
      RAISE EXCEPTION
        'Re-entry limit reached (% of %)',v_p.rebuys,v_t.max_reentries;
    END IF;
    IF p_rebuy_type='rebuy'
       AND COALESCE(v_p.chips,0)>COALESCE(v_t.starting_chips,0) THEN
      RAISE EXCEPTION 'Stack too high for a rebuy';
    END IF;
    /* CONSERVATION (a) 2026-09-11. A re-entry REPLACES the seat stack below
       (stack = v_add) while the roster gains rebuys + 1, so the conservation
       check's expected side gains rebuy_chips at the same moment. Taken while
       the entry still holds chips, that destroys them AND inflates expected.
       A re-entry follows a bust, so the live population for this is zero; it
       is refused rather than left to silently unbalance the event. */
    IF p_rebuy_type='reentry' AND COALESCE(v_p.chips,0)>0 THEN
      RAISE EXCEPTION
        'A Re-Entry Starts A New Stack And This Entry Still Holds % Chips - Aborting So No Charge Is Made',
        v_p.chips
        USING ERRCODE='55000';
    END IF;
    v_base:=COALESCE(NULLIF(v_t.rebuy_cost,0),v_t.buy_in_amount,0);
    v_add:=COALESCE(NULLIF(v_t.rebuy_chips,0),v_t.starting_chips,0)::integer;
  END IF;

  v_fee_ratio:=public.fn_ca_tournament_fee_ratio(
    v_t.buy_in_amount,v_t.buy_in_fee);
  v_ratio:=CASE WHEN p_rebuy_type='addon' THEN 0 ELSE v_fee_ratio END;
  v_total:=round(v_base::numeric);
  v_fee:=CASE WHEN v_ratio>0 AND v_total>0
    THEN public.fn_ca_recovery_fee_cents(
           round(v_total*100)::bigint,v_ratio,
           public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric/100    ELSE 0
  END;
  v_base:=round(v_total-v_fee,2);
  v_is_bounty:=COALESCE(v_t.is_bounty,false)
    OR COALESCE(v_t.is_pko,false)
    OR COALESCE(v_t.is_mystery_bounty,false);
  IF v_is_bounty AND p_rebuy_type<>'addon' THEN
    v_bounty_head:=public.fn_ca_unit_floor_cents(
      round(LEAST(GREATEST(0,round(COALESCE(v_t.bounty_amount,0),2)),
                  v_base)*100)::bigint,
      public.fn_ca_tournament_unit_cents(p_tournament_id))::numeric/100;
    v_base:=v_base-v_bounty_head;
  ELSE
    v_bounty_head:=0;
  END IF;
  IF p_cost IS NOT NULL AND abs(p_cost-v_total)>0.01 THEN
    RAISE EXCEPTION
      'Price mismatch: client quoted %, server computed %',p_cost,v_total
      USING ERRCODE='22023';
  END IF;
  IF v_add<=0 OR v_total<0 OR v_fee<0 OR v_base<0 OR v_bounty_head<0
     OR round(v_base+v_bounty_head+v_fee,2)<>round(v_total,2) THEN
    RAISE EXCEPTION 'Tournament chip-purchase quote does not conserve'
      USING ERRCODE='P0404';
  END IF;

  INSERT INTO public.wallet_credit_idempotency(key,user_id,amount)
  VALUES(v_key,p_user_id,v_total)
  ON CONFLICT(key) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  IF v_inserted=0 THEN
    RETURN jsonb_build_object(
      'success',true,'idempotent',true,'new_stack',v_p.chips,
      'rebuy_type',p_rebuy_type);
  END IF;

  IF v_unit = 100 THEN
    -- DIAMOND PHASE 8: the purchase reserves settled Diamonds into the entry's
    -- custody row. The chip-wallet debit below is the chip estate's.
    v_dia := public.fn_poker_diamond_tournament_charge(
      p_user_id, p_tournament_id, p_rebuy_type, v_total, v_base, v_bounty_head, v_fee, v_p.id, v_key);
    v_balance := 0;
  ELSE
  PERFORM public.fn_ensure_club_wallet(p_user_id,v_club);
  SELECT chip_balance INTO v_balance
    FROM public.club_members
   WHERE user_id=p_user_id AND club_id=v_club
   FOR UPDATE;
  IF v_balance IS NULL OR v_balance<v_total THEN
    RAISE EXCEPTION 'Insufficient club chips: need %, have %',
      v_total,COALESCE(v_balance,0);
  END IF;

  v_led_cat:=current_setting('app.ledger_category',true);
  v_led_cp:=current_setting('app.ledger_counterparty',true);
  v_led_ent:=current_setting('app.ledger_counterparty_entity',true);
  v_led_tid:=current_setting('app.ledger_tournament',true);
  PERFORM set_config('app.ledger_category',v_cat,true);
  PERFORM set_config('app.ledger_counterparty','prize_liability',true);
  PERFORM set_config(
    'app.ledger_counterparty_entity',p_tournament_id::text,true);
  PERFORM set_config('app.ledger_tournament',p_tournament_id::text,true);
  UPDATE public.club_members
     SET chip_balance=chip_balance-v_total,updated_at=now()
   WHERE user_id=p_user_id AND club_id=v_club;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'Exact tournament funding wallet changed during debit'
      USING ERRCODE='40001';
  END IF;
  END IF; -- DIAMOND PHASE 8: end of the chip-wallet branch
  PERFORM set_config('app.ledger_category',COALESCE(v_led_cat,''),true);
  PERFORM set_config('app.ledger_counterparty',COALESCE(v_led_cp,''),true);
  PERFORM set_config(
    'app.ledger_counterparty_entity',COALESCE(v_led_ent,''),true);
  PERFORM set_config('app.ledger_tournament',COALESCE(v_led_tid,''),true);

  IF p_rebuy_type='reentry' THEN
    UPDATE public.tournament_players
       SET chips=v_add,status='playing',eliminated_at=NULL,position=NULL,
           rebuys=COALESCE(rebuys,0)+1
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     RETURNING chips INTO v_new_chips;
  ELSIF p_rebuy_type='addon' THEN
    UPDATE public.tournament_players
       SET chips=COALESCE(chips,0)+v_add,add_on=true
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     RETURNING chips INTO v_new_chips;
  ELSE
    UPDATE public.tournament_players
       SET chips=COALESCE(chips,0)+v_add,status='playing',
           eliminated_at=NULL,position=NULL,
           rebuys=COALESCE(rebuys,0)+1
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     RETURNING chips INTO v_new_chips;
  END IF;
  IF v_new_chips IS NULL THEN
    RAISE EXCEPTION 'Locked tournament roster changed during chip grant'
      USING ERRCODE='40001';
  END IF;

  IF v_bounty_head>0 THEN
    UPDATE public.tournament_players
       SET current_bounty=CASE WHEN p_rebuy_type='reentry'
         THEN v_bounty_head
         ELSE COALESCE(current_bounty,0)+v_bounty_head END
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id;
  END IF;

  SELECT s.id,s.stack INTO v_seat
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE s.user_id=p_user_id AND s.left_at IS NULL
     AND tb.tournament_id=p_tournament_id
   ORDER BY (tb.status IS DISTINCT FROM 'closed') DESC,
            s.joined_at DESC NULLS LAST,s.id DESC
   LIMIT 1;
  IF FOUND THEN
    v_was_seated:=true;
    v_expected:=CASE WHEN p_rebuy_type='reentry'
      THEN v_add ELSE COALESCE(v_seat.stack,0)+v_add END;
    /* CONSERVATION (b) 2026-09-11. The roster above has already booked this
       purchase, so the supply this is measured against already contains the
       chips being bought. The felt must land inside it. An event that is
       already over its cap keeps playing; it may not get further over.
       See ca_drift_incidents 8b8fe26c and this migration's header. */
    PERFORM public.fn_ca_assert_tournament_chip_grant(
      p_tournament_id,p_user_id,v_seat.id,v_expected,
      'tournament '||p_rebuy_type);
    UPDATE public.table_seats
       SET stack=CASE WHEN p_rebuy_type='reentry'
         THEN v_add ELSE COALESCE(stack,0)+v_add END
     WHERE id=v_seat.id
     RETURNING stack INTO v_stack_after;
    IF v_stack_after IS NULL OR v_stack_after<>v_expected THEN
      RAISE EXCEPTION
        'Chip Grant Did Not Land: % Expected Stack %, Seat % Holds % - Aborting So No Charge Is Made',
        p_rebuy_type,v_expected,v_seat.id,v_stack_after;
    END IF;
    UPDATE public.tournament_players
       SET chips=(SELECT stack FROM public.table_seats WHERE id=v_seat.id)::integer
     WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     RETURNING chips INTO v_new_chips;
  ELSIF p_rebuy_type='addon' THEN
    RAISE EXCEPTION
      'Seat Disappeared During % - Aborting So No Charge Is Made',p_rebuy_type;
  END IF;

  UPDATE public.tournaments
     SET prize_pool=COALESCE(prize_pool,0)+v_base,
         bounty_pool=COALESCE(bounty_pool,0)+v_bounty_head
   WHERE id=p_tournament_id;
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 THEN
    RAISE EXCEPTION 'Tournament vanished during chip-purchase pool booking'
      USING ERRCODE='40001';
  END IF;

  IF v_fee>0 AND v_t.club_id IS NOT NULL AND v_unit = 100 THEN
    -- DIAMOND PHASE 8: the fee stays in custody until the event settles.
    UPDATE public.tournaments
       SET total_rake=COALESCE(total_rake,0)+v_fee
     WHERE id=p_tournament_id;
  ELSIF v_fee>0 AND v_t.club_id IS NOT NULL THEN
    INSERT INTO public.rake_records(
      hand_id,table_id,club_id,rake_amount,pot_size,num_players,
      bbj_contribution,is_tournament,tournament_id,source,metadata)
    VALUES(
      NULL,NULL,v_t.club_id,v_fee,v_fee,1,0,true,p_tournament_id,
      'process_tournament_rebuy',jsonb_build_object(
        'kind','tournament_'||p_rebuy_type||'_fee','user_id',p_user_id,
        'entry_club_id',v_club));
    UPDATE public.tournaments
       SET total_rake=COALESCE(total_rake,0)+v_fee
     WHERE id=p_tournament_id;
  END IF;

  IF v_unit = 1 THEN -- DIAMOND PHASE 8: wallet_transactions is the chip receipt
  INSERT INTO public.wallet_transactions(
    user_id,wallet_type,type,amount,category,description,
    related_entity_id,balance_after)
  VALUES(
    p_user_id,'PLAYER','debit',v_total,v_cat,
    'Tournament '||p_rebuy_type||': '||COALESCE(v_t.name,'tournament')||
      ' ('||v_base||' prize + '||v_bounty_head||' bounty + '||v_fee||
      ' fee) [club wallet]',
    p_tournament_id,v_balance-v_total);
  END IF; -- DIAMOND PHASE 8

  RETURN jsonb_build_object(
    'success',true,'new_stack',v_new_chips,'rebuy_type',p_rebuy_type,
    'chips_added',v_add,'cost',v_total,'fee',v_fee,'seated',v_was_seated,
    'bounty_head_funded',v_bounty_head);
END;
$function$;
ALTER FUNCTION public.fn_ca_process_tournament_chip_purchase_money_v1(uuid,uuid,text,numeric,numeric,integer,text) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_ca_process_tournament_chip_purchase_money_v1(uuid,uuid,text,numeric,numeric,integer,text) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_ca_process_tournament_chip_purchase_money_v1(uuid,uuid,text,numeric,numeric,integer,text) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_ca_settle_bounty_rebuy_generation_v1(uuid,uuid,uuid)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_ca_settle_bounty_rebuy_generation_v1(uuid,uuid,uuid)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_ca_settle_bounty_rebuy_generation_v1(p_tournament_id uuid, p_user_id uuid, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_obligation public.tournament_bounty_obligations%ROWTYPE;
  v_claim jsonb;
  v_result jsonb;
  v_reserve jsonb;
  v_award_id uuid;
  v_award_status text;
  v_chest_id uuid;
  v_seat_exit_token uuid;
  v_position integer;
  v_rows integer;
  v_head_after numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_user_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'Bounty rebuy requires one exact knockout generation'
      USING ERRCODE='22023';
  END IF;

  -- process_tournament_rebuy owns the terminal root, maintenance gate,
  -- tournament seat-acquisition root, and atomic table key before entering.
  -- Reacquire the exact rows here so this private step remains independently
  -- fail-closed if its caller ever drifts.
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id
   FOR UPDATE;
  IF NOT FOUND OR upper(COALESCE(v_t.status::text,''))<>'RUNNING'
     OR NOT (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
             OR COALESCE(v_t.is_mystery_bounty,false)) THEN
    RAISE EXCEPTION 'Bounty rebuy generation is not claimable'
      USING ERRCODE='55000';
  END IF;

  SELECT * INTO v_player
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND OR v_player.status::text NOT IN ('playing','eliminated')
     OR COALESCE(v_player.chips,0)<>0 OR COALESCE(v_player.prize,0)<>0 THEN
    RAISE EXCEPTION 'Only the exact unpaid zero-stack bounty entry may be replaced'
      USING ERRCODE='55000';
  END IF;

  PERFORM c.id
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
   ORDER BY c.hand_number,c.id
   FOR UPDATE;
  SELECT * INTO v_candidate
    FROM public.tournament_knockout_candidates c
   WHERE c.id=p_candidate_id
     AND c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_candidate.id IS DISTINCT FROM
          public.fn_ca_latest_committed_knockout_candidate(
            p_tournament_id,p_user_id)
     OR v_candidate.state NOT IN ('pending','eliminated') THEN
    RAISE EXCEPTION 'Bounty rebuy does not name the latest committed knockout generation'
      USING ERRCODE='P0404';
  END IF;

  SELECT * INTO v_obligation
    FROM public.tournament_bounty_obligations o
   WHERE o.tournament_id=p_tournament_id
     AND o.eliminated_user_id=p_user_id
     AND o.table_id=v_candidate.table_id
     AND o.hand_id=v_candidate.hand_id
     AND o.hand_number=v_candidate.hand_number
     AND o.seat_joined_at=v_candidate.seat_joined_at
   FOR UPDATE;

  IF NOT FOUND THEN
    -- A new obligation may be born here only for the still-open generation
    -- this purchase is replacing. An already-eliminated generation must carry
    -- its durable outbox; this path never reconstructs one from history.
    IF v_candidate.state<>'pending'
       OR v_player.status::text<>'playing'
       OR v_candidate.rebuy_prompt_until IS NULL
       OR v_candidate.rebuy_prompt_until<=clock_timestamp() THEN
      RAISE EXCEPTION 'Bounty rebuy cannot create a missing closed-generation obligation'
        USING ERRCODE='P0404';
    END IF;

    -- This is an entry-generation knockout, not a final tournament result.
    -- The existing outbox schema requires the field position observed at the
    -- status CAS; prize is exactly zero and the money core clears the temporary
    -- position again before the transaction can commit.
    SELECT GREATEST(2,count(*)::integer) INTO v_position
      FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.status='playing';

    -- The exact claim also retires the zero-stack chair. Keep the permanent
    -- seat-exit guard intact by opening its one-use elimination capability in
    -- this same transaction and requiring the claim to consume it exactly.
    v_seat_exit_token:=public.fn_ca_open_tournament_seat_exit_authority(
      p_tournament_id,'elimination',p_user_id);
    BEGIN
      v_claim:=public.fn_claim_bounty_legacy_candidate_20260907(
        p_tournament_id,p_user_id,v_position,0,
        v_candidate.table_id,v_candidate.hand_id,v_candidate.hand_number,
        v_candidate.seat_joined_at,NULL,NULL,0,false);
      PERFORM public.fn_ca_close_tournament_seat_exit_authority(
        v_seat_exit_token,
        COALESCE((v_claim->>'ok')::boolean,false)
          AND COALESCE((v_claim->>'claimed')::boolean,false));
    EXCEPTION WHEN OTHERS THEN
      PERFORM public.fn_ca_close_tournament_seat_exit_authority(
        v_seat_exit_token,false);
      RAISE;
    END;
    IF COALESCE((v_claim->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_claim->>'claimed')::boolean,false) IS NOT TRUE
       OR COALESCE(v_claim->>'obligation_id','')='' THEN
      RAISE EXCEPTION 'Atomic bounty rebuy claim refused: %',
        COALESCE(v_claim::text,'null') USING ERRCODE='P0404';
    END IF;

    SELECT * INTO v_obligation
      FROM public.tournament_bounty_obligations o
     WHERE o.id=(v_claim->>'obligation_id')::uuid
       AND o.tournament_id=p_tournament_id
       AND o.eliminated_user_id=p_user_id
       AND o.table_id=v_candidate.table_id
       AND o.hand_id=v_candidate.hand_id
       AND o.hand_number=v_candidate.hand_number
       AND o.seat_joined_at=v_candidate.seat_joined_at
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Atomic bounty rebuy claim returned no exact obligation'
        USING ERRCODE='P0404';
    END IF;
  END IF;

  IF v_obligation.state='settled' THEN
    IF NOT public.fn_bounty_obligation_has_complete_marker(v_obligation.id) THEN
      RAISE EXCEPTION 'Settled bounty rebuy obligation has no complete marker'
        USING ERRCODE='P0404';
    END IF;
  ELSIF v_obligation.mode='mystery_chest' THEN
    v_reserve:=public.fn_mystery_bounty_reserve(
      p_tournament_id,p_user_id,v_obligation.claimants,
      v_obligation.table_id,v_obligation.hand_id::text,
      md5('mb:'||v_obligation.id::text)::uuid,1);
    IF COALESCE((v_reserve->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE(v_reserve->>'obligation_id','')<>v_obligation.id::text
       OR COALESCE(v_reserve->>'recipients_verified','false')<>'true' THEN
      RAISE EXCEPTION 'Atomic mystery-bounty rebuy reserve refused: %',
        COALESCE(v_reserve::text,'null') USING ERRCODE='P0404';
    END IF;
    BEGIN
      v_award_id:=(v_reserve->>'award_id')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'Atomic mystery-bounty rebuy reserve returned no award id'
        USING ERRCODE='P0404';
    END;

    SELECT a.status,a.chest_id INTO v_award_status,v_chest_id
      FROM public.tournament_bounty_awards a
     WHERE a.id=v_award_id
       AND a.tournament_id=p_tournament_id
       AND a.eliminated_user_id=p_user_id
       AND a.bounty_obligation_id=v_obligation.id
     FOR UPDATE;
    IF NOT FOUND OR v_award_status NOT IN ('reserved','revealed','paid','completed') THEN
      RAISE EXCEPTION 'Atomic mystery-bounty rebuy award is not exact or payable'
        USING ERRCODE='P0404';
    END IF;

    -- The browser reveal RPC correctly trusts auth.uid(), so an authenticated
    -- busted player cannot impersonate the designated knocker. This owner-only
    -- purchase step performs the same two-row reveal transition under the
    -- already-held tournament lock before paying it immediately.
    IF v_award_status='reserved' THEN
      UPDATE public.tournament_bounty_awards a
         SET status='revealed',revealed_at=COALESCE(a.revealed_at,now())
       WHERE a.id=v_award_id AND a.status='reserved';
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION 'Atomic mystery-bounty rebuy award changed before reveal'
          USING ERRCODE='40001';
      END IF;
      UPDATE public.tournament_bounty_chests c
         SET status='revealed'
       WHERE c.id=v_chest_id AND c.status='reserved';
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION 'Atomic mystery-bounty rebuy chest changed before reveal'
          USING ERRCODE='40001';
      END IF;
    END IF;

    v_result:=public.fn_mystery_bounty_pay(v_award_id);
    IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE
       OR COALESCE((v_result->>'refused_recipients')::integer,0)<>0 THEN
      RAISE EXCEPTION 'Atomic mystery-bounty rebuy payment refused: %',
        COALESCE(v_result::text,'null') USING ERRCODE='P0404';
    END IF;
  ELSE
    v_result:=public.fn_collect_bounty_obligation(v_obligation.id);
    IF COALESCE((v_result->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Atomic bounty rebuy payment refused: %',
        COALESCE(v_result::text,'null') USING ERRCODE='P0404';
    END IF;
  END IF;

  SELECT * INTO v_obligation
    FROM public.tournament_bounty_obligations o
   WHERE o.id=v_obligation.id
   FOR UPDATE;
  IF NOT FOUND OR v_obligation.state<>'settled'
     OR NOT public.fn_bounty_obligation_has_complete_marker(v_obligation.id) THEN
    RAISE EXCEPTION 'Bounty rebuy old head did not produce its exact settled marker'
      USING ERRCODE='P0404';
  END IF;

  -- Fixed and PKO collection already clear the old head. Mystery payout owns a
  -- chest rather than current_bounty, so clear that same snapshotted generation
  -- here. A different nonzero head means the generation changed and must abort.
  SELECT tp.current_bounty INTO v_head_after
    FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF round(COALESCE(v_head_after,0),2)<>0
     AND round(COALESCE(v_head_after,0),2)<>round(v_obligation.head_amount,2) THEN
    RAISE EXCEPTION 'Bounty rebuy old head changed before retirement'
      USING ERRCODE='40001';
  END IF;
  UPDATE public.tournament_players tp
     SET current_bounty=0
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     AND round(COALESCE(tp.current_bounty,0),2) IN
           (0,round(v_obligation.head_amount,2));
  GET DIAGNOSTICS v_rows=ROW_COUNT;
  IF v_rows<>1 OR EXISTS (
    SELECT 1 FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
       AND round(COALESCE(tp.current_bounty,0),2)<>0
  ) THEN
    RAISE EXCEPTION 'Bounty rebuy old head was not retired exactly once'
      USING ERRCODE='P0404';
  END IF;

  RETURN jsonb_build_object(
    'ok',true,'obligation_id',v_obligation.id,
    'mode',v_obligation.mode,'old_head',v_obligation.head_amount,
    'marker_verified',true,'old_head_cleared',true);
END;
$function$;
ALTER FUNCTION public.fn_ca_settle_bounty_rebuy_generation_v1(uuid,uuid,uuid) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_ca_settle_bounty_rebuy_generation_v1(uuid,uuid,uuid) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_ca_settle_bounty_rebuy_generation_v1(uuid,uuid,uuid) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_ca_tournament_rebuy_window(uuid)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_ca_tournament_rebuy_window(uuid)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_ca_tournament_rebuy_window(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_now timestamptz:=clock_timestamp();
  v_level_cap integer;
  v_timed_deadline timestamptz;
  v_level_open boolean:=false;
  v_timed_open boolean:=false;
  v_addon_open boolean:=false;
  v_prompt_until timestamptz;
BEGIN
  IF p_tournament_id IS NULL THEN
    RAISE EXCEPTION 'tournament is required for rebuy-window policy'
      USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_t
    FROM public.tournaments t
   WHERE t.id=p_tournament_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tournament not found' USING ERRCODE='P0002';
  END IF;

  IF upper(COALESCE(v_t.status::text,''))<>'RUNNING'
     OR COALESCE(v_t.prize_pool_finalized,false)
     OR NOT (COALESCE(v_t.is_rebuy,false) OR COALESCE(v_t.is_reentry,false)) THEN
    RETURN jsonb_build_object(
      'open',false,'prompt_until',NULL,'reason','tournament_not_rebuyable');
  END IF;

  v_addon_open:=COALESCE(v_t.add_on_available,false)
    AND COALESCE(v_t.addon_period_triggered,false)
    AND v_t.addon_period_started_at IS NOT NULL
    AND v_t.addon_period_ends_at IS NOT NULL
    AND v_now>=v_t.addon_period_started_at
    AND v_now<v_t.addon_period_ends_at;
  v_level_cap:=COALESCE(
    NULLIF(v_t.rebuy_levels,0),NULLIF(v_t.late_reg_levels,0),0);
  v_level_open:=v_level_cap>0
    AND v_t.current_level IS NOT NULL
    AND v_t.current_level<v_level_cap;
  IF v_level_cap<=0 AND COALESCE(v_t.late_reg_mins,0)>0
     AND v_t.started_at IS NOT NULL THEN
    v_timed_deadline:=v_t.started_at+
      make_interval(mins=>v_t.late_reg_mins);
    v_timed_open:=v_now<v_timed_deadline;
  END IF;

  IF NOT (v_level_open OR v_timed_open OR v_addon_open) THEN
    RETURN jsonb_build_object(
      'open',false,'prompt_until',NULL,'reason','rebuy_window_closed',
      'level_cap',v_level_cap,'addon_open',v_addon_open);
  END IF;
  v_prompt_until:=LEAST(
    v_now+interval '30 seconds',
    GREATEST(
      CASE WHEN v_level_open THEN v_now+interval '30 seconds' END,
      CASE WHEN v_timed_open THEN v_timed_deadline END,
      CASE WHEN v_addon_open THEN v_t.addon_period_ends_at END));
  RETURN jsonb_build_object(
    'open',true,'prompt_until',v_prompt_until,'reason','open',
    'level_cap',v_level_cap,'level_open',v_level_open,
    'timed_open',v_timed_open,'addon_open',v_addon_open);
END;
$function$;
ALTER FUNCTION public.fn_ca_tournament_rebuy_window(uuid) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_ca_tournament_rebuy_window(uuid) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_ca_tournament_rebuy_window(uuid) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_claim_bounty_legacy_candidate_20260907(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_claim_bounty_legacy_candidate_20260907(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_claim_bounty_legacy_candidate_20260907(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric DEFAULT 0, p_allow_existing_eliminated boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_atomic public.hand_atomic_commits%ROWTYPE;
  v_settlement_at timestamptz;
  v_settlement_hand_text text;
  v_settlement_hand_id uuid;
  v_mode text;
  v_claimants jsonb;
  v_input_claimants jsonb;
  v_knocker uuid;
  v_head numeric;
  v_hand_created_at timestamptz;
  v_position integer;
  v_prize numeric;
  v_claimed boolean := false;
  v_existing public.tournament_bounty_obligations%ROWTYPE;
  v_obligation_id uuid;
  v_activation_generation bigint := 0;
  v_pko_watermark bigint;
  v_bounty_blocked text := NULL;
  v_predecessors jsonb;
  v_activated_at timestamptz;
  v_bust_at timestamptz;
BEGIN
  IF p_tournament_id IS NULL OR p_eliminated_user_id IS NULL
     OR p_table_id IS NULL OR p_hand_id IS NULL OR p_hand_number IS NULL
     OR p_hand_number<1000000 OR p_seat_joined_at IS NULL
     OR p_bubble_refund IS NULL OR p_bubble_refund<0 THEN
    RETURN jsonb_build_object('ok',false,'reason','missing_identity');
  END IF;
  IF p_bubble_refund<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','bubble_refund_requires_finalized_batch');
  END IF;

  IF p_claimants IS NOT NULL THEN
    IF jsonb_typeof(p_claimants)<>'array' OR jsonb_array_length(p_claimants)=0
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(p_claimants) e
          WHERE coalesce(e->>'user_id','')
                  !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             OR coalesce(e->>'weight','') !~ '^[0-9]+([.][0-9]+)?$'
             OR (e->>'weight')::numeric<=0
       ) THEN
      RETURN jsonb_build_object('ok',false,'reason','invalid_claimants');
    END IF;
    SELECT jsonb_agg(jsonb_build_object('user_id',user_id,'weight',1)
                     ORDER BY user_id::text)
      INTO v_input_claimants
      FROM (
        SELECT DISTINCT (e->>'user_id')::uuid AS user_id
          FROM jsonb_array_elements(p_claimants) e
      ) q;
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;

  -- A hand triple is the immutable replay key. Two legitimate bounties may
  -- have the same player and seat_joined_at after a same-chair rebuy.
  SELECT * INTO v_existing
    FROM public.tournament_bounty_obligations o
   WHERE o.tournament_id=p_tournament_id
     AND o.table_id=p_table_id
     AND o.hand_id=p_hand_id
     AND o.hand_number=p_hand_number
     AND o.eliminated_user_id=p_eliminated_user_id
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.table_id IS DISTINCT FROM p_table_id
       OR v_existing.hand_id IS DISTINCT FROM p_hand_id
       OR v_existing.seat_joined_at IS DISTINCT FROM p_seat_joined_at
       OR v_existing.bubble_refund IS DISTINCT FROM round(p_bubble_refund,2)
       OR v_existing.position IS DISTINCT FROM p_position
       OR v_existing.prize IS DISTINCT FROM round(p_prize,2)
       OR (p_knocker_user_id IS NOT NULL AND NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(v_existing.claimants) c
              WHERE c->>'user_id'=p_knocker_user_id::text))
       OR (v_input_claimants IS NOT NULL
           AND v_existing.claimants IS DISTINCT FROM v_input_claimants) THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','obligation_identity_conflict');
    END IF;
    IF v_existing.state='settled'
       AND NOT public.fn_bounty_obligation_has_complete_marker(v_existing.id) THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','settled_marker_incomplete',
        'obligation_id',v_existing.id);
    END IF;
    RETURN jsonb_build_object(
      'ok',true,'already',true,'claimed',false,
      'mode',v_existing.mode,'state',v_existing.state,
      'activation_generation',v_existing.activation_generation,
      'obligation_id',v_existing.id);
  END IF;

  IF NOT (coalesce(v_t.is_bounty,false) OR coalesce(v_t.is_pko,false)
          OR coalesce(v_t.is_mystery_bounty,false)) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_bounty_tournament');
  END IF;
  IF upper(coalesce(v_t.status,''))<>'RUNNING'
     AND NOT (p_allow_existing_eliminated
              AND upper(coalesce(v_t.status,''))='COMPLETING') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','tournament_lifecycle_not_claimable',
      'status',v_t.status);
  END IF;

  SELECT * INTO v_player FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id=p_eliminated_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_found');
  END IF;
  IF coalesce(v_player.chips,0)>0 THEN
    RETURN jsonb_build_object('ok',false,'reason','player_has_chips');
  END IF;
  IF v_player.status<>'playing' THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','status_not_claimable','status',v_player.status);
  END IF;
  IF p_position IS NULL OR p_position<2 OR p_prize IS NULL OR p_prize<0 THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_place_or_prize');
  END IF;
  v_position:=p_position;
  v_prize:=p_prize;

  SELECT a.* INTO v_atomic
    FROM public.hand_atomic_commits a
   WHERE a.table_id=p_table_id
     AND a.hand_number=p_hand_number
     AND a.hand_id=p_hand_id;
  IF NOT FOUND THEN
    IF EXISTS (
      SELECT 1 FROM public.hand_atomic_commits a
       WHERE a.table_id=p_table_id AND a.hand_number=p_hand_number
    ) THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','atomic_knockout_history_identity_conflict');
    END IF;
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_evidence_required');
  END IF;

  v_settlement_hand_text:=v_atomic.stack_result->>'hand_id';
  IF coalesce(v_settlement_hand_text,'')
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_atomic.stack_result->>'table_id'<>p_table_id::text
     OR coalesce(v_atomic.stack_result->>'hand_number','')
          !~ '^[0-9]+$'
     OR (v_atomic.stack_result->>'hand_number')::bigint<>p_hand_number
     OR coalesce(v_atomic.stack_result->'written'
                   ->>p_eliminated_user_id::text,'')
          !~ '^-?[0-9]+([.][0-9]+)?$'
     OR (v_atomic.stack_result->'written'
           ->>p_eliminated_user_id::text)::numeric<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_candidate_identity_conflict');
  END IF;
  v_settlement_hand_id:=v_settlement_hand_text::uuid;

  SELECT c.* INTO v_candidate
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.table_id=p_table_id
     AND c.hand_number=p_hand_number
     AND c.hand_id=p_hand_id
     AND c.eliminated_user_id=p_eliminated_user_id;
  IF NOT FOUND
     OR v_candidate.seat_joined_at IS DISTINCT FROM p_seat_joined_at THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_candidate_identity_conflict');
  END IF;

  SELECT k.completed_at INTO v_settlement_at
    FROM public.settlement_idempotency_keys k
   WHERE k.table_id=p_table_id
     AND k.hand_id=v_settlement_hand_id
     AND k.status='succeeded'
     AND k.completed_at IS NOT NULL
     AND k.completed_at>=p_seat_joined_at
     AND coalesce(k.result->>'hand_number','') ~ '^[0-9]+$'
     AND (k.result->>'hand_number')::bigint=p_hand_number
     AND k.result->>'table_id'=p_table_id::text
     AND k.result->'written' ? p_eliminated_user_id::text
     AND coalesce(k.result->'written'->>p_eliminated_user_id::text,'')
           ~ '^-?[0-9]+([.][0-9]+)?$'
     AND (k.result->'written'->>p_eliminated_user_id::text)::numeric=0;
  IF v_settlement_at IS NULL THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','accepted_zero_settlement_not_found');
  END IF;

  SELECT h.created_at INTO v_hand_created_at
    FROM public.hand_history h
   WHERE h.id=p_hand_id
     AND h.table_id=p_table_id
     AND h.hand_number=p_hand_number
     AND h.hand_number>=1000000
     AND h.created_at>=v_settlement_at
     AND h.created_at>=p_seat_joined_at
     AND EXISTS (
       SELECT 1 FROM jsonb_array_elements(coalesce(h.players,'[]'::jsonb)) player
        WHERE coalesce(player->>'userId',player->>'user_id')=
                p_eliminated_user_id::text
          AND coalesce(player->>'stack','') ~ '^-?[0-9]+([.][0-9]+)?$'
          AND (player->>'stack')::numeric=0
     );
  IF v_hand_created_at IS NULL THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','exact_knockout_history_not_found');
  END IF;

  v_claimants:=public.fn_exact_tournament_knockout_claimants(
    p_tournament_id,p_hand_id,p_eliminated_user_id);
  IF v_claimants IS NULL OR jsonb_array_length(v_claimants)=0 THEN
    /* A PLACE IS NOT A BOUNTY (2026-09-10).
       fn_exact_tournament_knockout_claimants returns NULL when it cannot
       name the exact winner of the last pot the busted player was eligible
       for, and it is right to refuse to guess. That is a reason not to PAY
       a bounty. It is not a reason to withhold a finishing place from a
       player who provably busted - refusing here left 33 busts unrecorded
       across nine events and held their prize escrow for days. */
    v_bounty_blocked:='exact_pot_claimants_not_found';
    v_claimants:='[]'::jsonb;
  END IF;
  SELECT (e->>'user_id')::uuid INTO v_knocker
    FROM jsonb_array_elements(v_claimants) e
   ORDER BY e->>'user_id' LIMIT 1;
  IF v_bounty_blocked IS NULL AND p_knocker_user_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_claimants) e
        WHERE e->>'user_id'=p_knocker_user_id::text
     ) THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_knocker');
  END IF;
  IF v_bounty_blocked IS NULL AND v_input_claimants IS NOT NULL
     AND v_input_claimants IS DISTINCT FROM v_claimants THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','claimants_do_not_match_exact_pot');
  END IF;

  /* A BUST BELONGS TO THE PHASE ITS HAND WAS PLAYED IN (2026-09-11).
     The stage at the moment a claim is RECORDED says nothing about when the
     bust happened: a claim backlog recorded 06:27 busts at 13:57 as chest
     knockouts and spent another event's chests on them. v_atomic is the exact,
     identity-verified hand_atomic_commits row of the claimed hand; the sealed
     activation receipt of the current generation is the other end. Earlier ->
     the pre-activation mode the bust would have had. Later -> a chest. No
     receipt -> refused, as before. Order not provable -> the place is
     recorded and no bounty is paid (A PLACE IS NOT A BOUNTY). */
  IF coalesce(v_t.is_mystery_bounty,false)
     AND coalesce(v_t.mystery_bounty_stage,'pending')<>'pending' THEN
    v_activation_generation:=coalesce(v_t.mystery_bounty_activation_generation,0);
    SELECT ar.activated_at INTO v_activated_at
      FROM public.tournament_mystery_activation_receipts ar
     WHERE ar.tournament_id=p_tournament_id
       AND ar.activation_generation=v_activation_generation;
    IF v_activation_generation<=0 OR v_activated_at IS NULL THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','mystery_activation_evidence_missing');
    END IF;
    IF v_atomic.committed_at IS NOT NULL
       AND v_atomic.committed_at>v_activated_at THEN
      v_mode:='mystery_chest';
    ELSE
      v_mode:=CASE WHEN coalesce(v_t.is_pko,false) THEN 'pko'
                   ELSE 'mystery_pre' END;
      v_activation_generation:=0;
      IF v_atomic.committed_at IS NULL
         OR v_atomic.committed_at>=v_activated_at THEN
        v_bounty_blocked:=COALESCE(v_bounty_blocked,
                                   'mystery_phase_of_bust_not_proven');
      END IF;
    END IF;
  ELSE
    v_mode:=CASE
      WHEN coalesce(v_t.is_pko,false) THEN 'pko'
      WHEN coalesce(v_t.is_mystery_bounty,false) THEN 'mystery_pre'
      ELSE 'regular'
    END;
    v_activation_generation:=0;
  END IF;

  IF v_mode='pko' THEN
    v_predecessors:=public.fn_pko_claim_predecessor_status_v1(
      p_tournament_id,p_eliminated_user_id,p_table_id,p_hand_id,
      p_hand_number,p_seat_joined_at);
    IF v_predecessors->>'ok' IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('ok',false,'reason','pko_predecessor_not_ready',
                               'predecessor_proof',v_predecessors);
    END IF;
  END IF;

  IF v_mode='pko' THEN
    SELECT w.last_settled_hand_number INTO v_pko_watermark
      FROM public.tournament_pko_settlement_watermarks w
     WHERE w.tournament_id=p_tournament_id FOR UPDATE;
    IF v_pko_watermark IS NOT NULL AND p_hand_number<v_pko_watermark THEN
      v_predecessors:=public.fn_pko_watermark_admission_status_v1(
        p_tournament_id,p_eliminated_user_id,p_table_id,p_hand_id,
        p_hand_number,p_seat_joined_at,v_claimants);
      IF v_predecessors->>'ok' IS DISTINCT FROM 'true' THEN
        RETURN jsonb_build_object('ok',false,'reason','pko_order_unproven',
          'watermark_proof',v_predecessors);
      END IF;
    END IF;
  END IF;

  IF v_bounty_blocked IS NULL AND v_mode='pko' AND EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations prior
     WHERE prior.tournament_id=p_tournament_id
       AND prior.mode='pko' AND prior.state='pending'
       AND (prior.hand_number<p_hand_number
            OR (prior.hand_number=p_hand_number
                AND prior.eliminated_user_id::text<
                    p_eliminated_user_id::text))
       AND EXISTS (
         SELECT 1 FROM jsonb_array_elements(prior.claimants) c
          WHERE c->>'user_id'=p_eliminated_user_id::text
       )
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','pending_pko_predecessor');
  END IF;

  IF v_bounty_blocked IS NULL AND v_mode='pko' AND EXISTS (
    SELECT 1
      FROM public.hand_history h
      CROSS JOIN LATERAL
        jsonb_array_elements(coalesce(h.players,'[]'::jsonb)) hp
     WHERE h.id=p_hand_id
       AND coalesce(hp->>'userId',hp->>'user_id','')
             ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND coalesce(hp->>'userId',hp->>'user_id')<>
             p_eliminated_user_id::text
       AND coalesce(hp->>'stack','') ~ '^-?[0-9]+([.][0-9]+)?$'
       AND (hp->>'stack')::numeric<=0
       AND public.fn_exact_tournament_knockout_claimants(
             p_tournament_id,h.id,
             coalesce(hp->>'userId',hp->>'user_id')::uuid)
             @> jsonb_build_array(jsonb_build_object(
                  'user_id',p_eliminated_user_id,'weight',1))
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_obligations predecessor
          WHERE predecessor.tournament_id=p_tournament_id
            AND predecessor.hand_number=p_hand_number
            AND predecessor.eliminated_user_id=
                coalesce(hp->>'userId',hp->>'user_id')::uuid
            AND predecessor.state='settled'
       )
  ) THEN
    RETURN jsonb_build_object('ok',false,'reason','same_hand_pko_predecessor');
  END IF;

  v_head:=coalesce(nullif(v_player.current_bounty,0),
                   nullif(v_t.bounty_amount,0));
  IF coalesce(v_head,0)<=0 THEN
    v_bounty_blocked:=COALESCE(v_bounty_blocked,'exact_head_value_not_found');
  END IF;

  /* A BUST IS RANKED BY WHEN IT HAPPENED (2026-09-11). eliminated_at was
     now(), the moment this claim was accepted, so a bust accepted late was
     stamped later than busts that came after it. It is now the time of the
     bust, by the rule the non-bounty door stamps and
     fn_settle_tournament_places ranks with: the commit time of the accepted
     hand this claim is bound to, plus one microsecond per earlier rank in
     that hand - smaller hand-start stack first, then user id. A bust whose
     hand cannot be read is refused, never stamped with the clock; so is a
     generation the player provably played on from - a posted rebuy leg
     after it AND a later hand of this event that deals the player in - since
     its hand is then not the bust and nothing here can say which one is. */
  SELECT a.committed_at
         + (SELECT count(*)
              FROM public.tournament_knockout_candidates s
             WHERE s.tournament_id=c.tournament_id
               AND s.table_id=c.table_id
               AND s.hand_number=c.hand_number
               AND s.hand_id=c.hand_id
               AND (s.stack_before,s.eliminated_user_id)
                   <(c.stack_before,c.eliminated_user_id))::integer
           * interval '1 microsecond'
    INTO v_bust_at
    FROM public.tournament_knockout_candidates c
    JOIN public.hand_atomic_commits a
      ON a.table_id=c.table_id
     AND a.hand_number=c.hand_number
     AND a.hand_id=c.hand_id
   WHERE c.id=v_candidate.id
     AND c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_eliminated_user_id
     AND c.state='pending';
  IF v_bust_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','knockout_bust_time_unproven');
  END IF;
  IF EXISTS (
       SELECT 1 FROM public.chip_ledger l
        WHERE l.from_entity_id=p_eliminated_user_id
          AND l.tournament_id=p_tournament_id
          AND l.category='rebuy'
          AND l.from_type='player_wallet'
          AND l.to_type='prize_liability'
          AND l.status='posted'
          AND l.amount>0
          AND l.created_at>v_candidate.created_at)
     AND EXISTS (
       SELECT 1 FROM public.hand_history h
        WHERE h.tournament_id=p_tournament_id
          AND h.hand_number>p_hand_number
          AND (h.players @> jsonb_build_array(jsonb_build_object(
                 'userId',p_eliminated_user_id::text))
               OR h.players @> jsonb_build_array(jsonb_build_object(
                 'user_id',p_eliminated_user_id::text)))) THEN
    /* Nothing newer can bind this player, who stays 'playing' at zero
       chips, so this refusal would hold the event open for ever without a
       word. It is written where the money board reads - once: one open alert
       per player. */
    INSERT INTO public.financial_alerts(severity,source,message,context)
    SELECT 'critical','knockout_door.payout_blocked_by_unrecordable_bust',
      'A busted player cannot be recorded, so the tournament cannot finish: '
        ||'the only knockout generation left to record them by is one they '
        ||'rebought from and played on after, and no later bust was captured. '
        ||'Their place needs a ruling from their last hand.',
      jsonb_build_object('tournament_id',p_tournament_id,'user_id',p_eliminated_user_id,
        'reason','knockout_bust_time_unproven',
        'detail','played_on_after_a_rebuy','hand_number',p_hand_number)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source='knockout_door.payout_blocked_by_unrecordable_bust'
          AND NOT fa.resolved
          AND fa.context->>'tournament_id'=p_tournament_id::text
          AND fa.context->>'user_id'=p_eliminated_user_id::text);
    RETURN jsonb_build_object('ok',false,'reason','knockout_bust_time_unproven',
                              'detail','played_on_after_a_rebuy');
  END IF;

  UPDATE public.tournament_players tp
     SET status='eliminated',position=p_position,prize=p_prize,
         eliminated_at=v_bust_at
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id=p_eliminated_user_id
     AND tp.status='playing' AND tp.chips<=0;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'bounty elimination CAS missed after locked claim'
      USING ERRCODE='serialization_failure';
  END IF;
  v_claimed:=true;

  IF v_bounty_blocked IS NULL THEN
  INSERT INTO public.tournament_bounty_obligations(
    tournament_id,eliminated_user_id,table_id,hand_id,hand_number,
    settlement_completed_at,seat_joined_at,position,prize,bubble_refund,
    mode,activation_generation,head_amount,knocker_user_id,claimants,
    next_attempt_at)
  VALUES (
    p_tournament_id,p_eliminated_user_id,p_table_id,p_hand_id,p_hand_number,
    v_settlement_at,p_seat_joined_at,v_position,round(v_prize,2),0,
    v_mode,v_activation_generation,round(v_head,2),v_knocker,v_claimants,
    CASE WHEN v_mode='mystery_chest' THEN now()+interval '30 seconds'
         ELSE now() END)
  RETURNING id INTO v_obligation_id;
  ELSE
    /* The bust is recorded and placed above. The head could not be
       attributed, so no obligation is written: fn_tournament_has_unsettled_bounties
       only sees obligations that EXIST, so the event can finish, and the
       head stays in tournaments.bounty_pool for fn_finalize_bounty_pool to
       resolve as residual with its own completion receipt. This row is the
       record that it happened - severity `warning`, so
       fn_ca_financial_alert_to_incident (which promotes only `critical`)
       does not raise a board item per bust. A listed fact, not an alarm. */
    INSERT INTO public.financial_alerts(severity,source,message,context)
    VALUES ('warning',
      'fn_claim_tournament_bounty_elimination.bounty_head_not_attributed',
      'A bust was recorded and placed, but its bounty head could not be '
        ||'attributed ('||v_bounty_blocked||'); the head stays in the '
        ||'bounty pool as residual.',
      jsonb_build_object('tournament_id',p_tournament_id,
        'eliminated_user_id',p_eliminated_user_id,'table_id',p_table_id,
        'hand_id',p_hand_id,'hand_number',p_hand_number,
        'position',v_position,'head_amount',round(coalesce(v_head,0),2),
        'mode',v_mode,'reason',v_bounty_blocked));
  END IF;

  UPDATE public.table_seats s
     SET left_at=coalesce(s.left_at,now())
   WHERE s.table_id=p_table_id AND s.user_id=p_eliminated_user_id
     AND s.joined_at=p_seat_joined_at AND s.left_at IS NULL;
  UPDATE public.tables tb
     SET current_players=(
       SELECT count(*) FROM public.table_seats s
        WHERE s.table_id=p_table_id AND s.left_at IS NULL)
   WHERE tb.id=p_table_id;
  PERFORM public.fn_sync_seat_first_player_count(p_tournament_id);

  UPDATE public.tournament_bounty_obligations o
     SET state='settled',settled_at=now()
   WHERE o.id=v_obligation_id
     AND public.fn_bounty_obligation_has_complete_marker(o.id);

  RETURN jsonb_build_object(
    'ok',true,'already',false,'claimed',v_claimed,'mode',v_mode,
    'bounty_blocked',v_bounty_blocked,
    'state',(SELECT o.state FROM public.tournament_bounty_obligations o
              WHERE o.id=v_obligation_id),
    'activation_generation',v_activation_generation,'bubble_refund',0,
    'obligation_id',v_obligation_id);
END;
$function$;
ALTER FUNCTION public.fn_claim_bounty_legacy_candidate_20260907(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_claim_bounty_legacy_candidate_20260907(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_claim_bounty_legacy_candidate_20260907(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_claim_tournament_bounty_elimination(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_claim_tournament_bounty_elimination(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_claim_tournament_bounty_elimination(p_tournament_id uuid, p_eliminated_user_id uuid, p_position integer, p_prize numeric, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_knocker_user_id uuid, p_claimants jsonb, p_bubble_refund numeric DEFAULT 0, p_allow_existing_eliminated boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_resolved_candidate_id uuid;
  v_atomic public.hand_atomic_commits%ROWTYPE;
  v_live public.table_seats%ROWTYPE;
  v_evidence_stack numeric;
  v_settlement_hand_text text;
  v_settlement_hand_id uuid;
  v_live_count integer;
  v_changed integer;
  v_result jsonb;
  v_rebought_generations uuid[] := ARRAY[]::uuid[];
BEGIN
  -- Exact replay is permitted after the player, seat and tournament have moved
  -- on. The immutable obligation itself is the receipt, and the private core
  -- verifies every caller-supplied field against it.
  IF p_tournament_id IS NULL OR p_eliminated_user_id IS NULL
     OR p_hand_number IS NULL THEN
    RETURN public.fn_claim_bounty_legacy_candidate_20260907(
      p_tournament_id,p_eliminated_user_id,p_position,p_prize,p_table_id,
      p_hand_id,p_hand_number,p_seat_joined_at,p_knocker_user_id,p_claimants,
      p_bubble_refund,p_allow_existing_eliminated);
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations o
     WHERE o.tournament_id=p_tournament_id
       AND o.table_id=p_table_id
       AND o.hand_id=p_hand_id
       AND o.hand_number=p_hand_number
       AND o.eliminated_user_id=p_eliminated_user_id
  ) THEN
    RETURN public.fn_claim_bounty_legacy_candidate_20260907(
      p_tournament_id,p_eliminated_user_id,p_position,p_prize,p_table_id,
      p_hand_id,p_hand_number,p_seat_joined_at,p_knocker_user_id,p_claimants,
      p_bubble_refund,p_allow_existing_eliminated);
  END IF;

  SELECT * INTO v_player FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id
     AND tp.user_id=p_eliminated_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_found');
  END IF;

  PERFORM 1
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_eliminated_user_id
   ORDER BY c.hand_number,c.id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','knockout_candidate_required');
  END IF;

  v_resolved_candidate_id:=public.fn_ca_latest_committed_knockout_candidate(
    p_tournament_id,p_eliminated_user_id);
  SELECT c.* INTO v_candidate
    FROM public.tournament_knockout_candidates c
   WHERE c.id=v_resolved_candidate_id;
  IF NOT FOUND
     OR v_candidate.table_id IS DISTINCT FROM p_table_id
     OR v_candidate.hand_id IS DISTINCT FROM p_hand_id
     OR v_candidate.hand_number IS DISTINCT FROM p_hand_number
     OR v_candidate.seat_joined_at IS DISTINCT FROM p_seat_joined_at THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','bounty_claim_is_not_latest_knockout_hand');
  END IF;

  SELECT a.* INTO v_atomic
    FROM public.hand_atomic_commits a
   WHERE a.table_id=v_candidate.table_id
     AND a.hand_number=v_candidate.hand_number
     AND a.hand_id=v_candidate.hand_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_candidate_missing');
  END IF;
  v_settlement_hand_text:=v_atomic.stack_result->>'hand_id';
  IF coalesce(v_settlement_hand_text,'')
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_atomic.stack_result->>'table_id'<>v_candidate.table_id::text
     OR coalesce(v_atomic.stack_result->>'hand_number','')
          !~ '^[0-9]+$'
     OR (v_atomic.stack_result->>'hand_number')::bigint<>
          v_candidate.hand_number
     OR coalesce(v_atomic.stack_result->'written'
                   ->>p_eliminated_user_id::text,'')
          !~ '^-?[0-9]+([.][0-9]+)?$'
     OR (v_atomic.stack_result->'written'
           ->>p_eliminated_user_id::text)::numeric<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_candidate_identity_conflict');
  END IF;
  v_settlement_hand_id:=v_settlement_hand_text::uuid;

  SELECT (k.result->'written'
            ->>p_eliminated_user_id::text)::numeric
    INTO v_evidence_stack
    FROM public.settlement_idempotency_keys k
   WHERE k.table_id=v_candidate.table_id
     AND k.hand_id=v_settlement_hand_id
     AND k.status='succeeded'
     AND k.completed_at IS NOT NULL
     AND k.result->>'table_id'=v_candidate.table_id::text
     AND coalesce(k.result->>'hand_number','') ~ '^[0-9]+$'
     AND (k.result->>'hand_number')::bigint=v_candidate.hand_number
     AND coalesce(k.result->'written'
                   ->>p_eliminated_user_id::text,'')
           ~ '^-?[0-9]+([.][0-9]+)?$';
  IF NOT FOUND OR v_evidence_stack<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','exact_knockout_settlement_receipt_missing');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_eliminated_user_id
       AND c.hand_number>v_candidate.hand_number
  ) THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','latest_knockout_evidence_chain_conflict');
  END IF;
  /* A GENERATION A REBUY PAID FOR IS NOT A LIVE BUST (2026-09-11).
     The 2026-09-08/09 rebuy chain bought players back in without marking the
     busted generation 'rebought', so each left an older 'pending' row, and
     this check then refused every later, real bust of the same player for
     ever. The non-bounty door's rule applies here too: a pending generation
     is proven bought back when a posted 'rebuy' leg moved this player's own
     wallet into this event's prize liability AFTER that generation was
     captured and BEFORE the player's next generation was. A bounty adds one
     condition: the older generation's head must already be COLLECTED. A
     bounty rebuy settles the replaced generation's head before the purchase
     completes (fn_ca_settle_bounty_rebuy_generation_v1), so a proven
     generation is resolved only when its own bounty obligation exists and
     every obligation that names its hand or its chair is settled with its
     complete marker. A generation no obligation names never had its head
     collected: that head is still owed to whoever took the stack in that
     hand, and a rebuy adds the new head on top of it, so resolving it here
     would hand both heads to the player's next knocker. An obligation still
     owed would be collected against a player this claim is about to record
     under a newer head. Both stay refused, and the refusal raises an alert
     for a ruling. Only proven rows are resolved, only in the transaction
     that records the newer bust; anything unproven is refused exactly as
     before. */
  SELECT COALESCE(array_agg(c.id ORDER BY c.hand_number,c.id),ARRAY[]::uuid[])
    INTO v_rebought_generations
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_eliminated_user_id
     AND c.hand_number<v_candidate.hand_number
     AND c.state='pending'
     AND (
       -- DIAMOND PHASE 8: a Diamond rebuy or re-entry is a Diamond ledger
       -- row, not a chip leg; it proves the generation the same way.
       EXISTS (
       SELECT 1 FROM public.poker_diamond_tournament_ledger d
        WHERE d.user_id=p_eliminated_user_id
          AND d.tournament_id=p_tournament_id
          AND d.kind IN ('rebuy','reentry')
          AND d.amount>0
          AND d.created_at>c.created_at
          AND d.created_at<(
            SELECT n.created_at
              FROM public.tournament_knockout_candidates n
             WHERE n.tournament_id=p_tournament_id
               AND n.eliminated_user_id=p_eliminated_user_id
               AND n.hand_number>c.hand_number
             ORDER BY n.hand_number,n.id
             LIMIT 1))
       OR EXISTS (
       SELECT 1 FROM public.chip_ledger l
        WHERE l.from_entity_id=p_eliminated_user_id
          AND l.tournament_id=p_tournament_id
          AND l.category='rebuy'
          AND l.from_type='player_wallet'
          AND l.to_type='prize_liability'
          AND l.status='posted'
          AND l.amount>0
          AND l.created_at>c.created_at
          AND l.created_at<(
            SELECT n.created_at
              FROM public.tournament_knockout_candidates n
             WHERE n.tournament_id=p_tournament_id
               AND n.eliminated_user_id=p_eliminated_user_id
               AND n.hand_number>c.hand_number
             ORDER BY n.hand_number,n.id
             LIMIT 1)))
     AND EXISTS (
       SELECT 1 FROM public.tournament_bounty_obligations o
        WHERE o.tournament_id=p_tournament_id
          AND o.eliminated_user_id=p_eliminated_user_id
          AND o.table_id=c.table_id
          AND o.hand_id=c.hand_id
          AND o.hand_number=c.hand_number)
     AND NOT EXISTS (
       SELECT 1 FROM public.tournament_bounty_obligations o
        WHERE o.tournament_id=p_tournament_id
          AND o.eliminated_user_id=p_eliminated_user_id
          AND (o.hand_number=c.hand_number
               OR o.seat_joined_at=c.seat_joined_at)
          AND NOT (o.state='settled'
                   AND public.fn_bounty_obligation_has_complete_marker(o.id)));
  IF EXISTS (
    SELECT 1 FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_eliminated_user_id
       AND c.hand_number<v_candidate.hand_number
       AND c.state<>'rebought'
       AND c.id<>ALL(v_rebought_generations)
  ) THEN
    /* This refusal cannot clear by itself - no newer generation will make
       the older one proven - so it would hold the event open for ever
       without a word. It is written where the money board reads - once: one
       open alert per player. */
    INSERT INTO public.financial_alerts(severity,source,message,context)
    SELECT 'critical','knockout_door.payout_blocked_by_unrecordable_bust',
      'A busted player cannot be recorded, so the tournament cannot finish: '
        ||'an older knockout generation of theirs is neither rebought nor '
        ||'proven bought back (a posted rebuy leg after it and, in a bounty '
        ||'event, its head collected). That generation needs a ruling.',
      jsonb_build_object('tournament_id',p_tournament_id,'user_id',p_eliminated_user_id,
        'reason','unresolved_knockout_generation_chain',
        'hand_number',v_candidate.hand_number)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source='knockout_door.payout_blocked_by_unrecordable_bust'
          AND NOT fa.resolved
          AND fa.context->>'tournament_id'=p_tournament_id::text
          AND fa.context->>'user_id'=p_eliminated_user_id::text);
    RETURN jsonb_build_object(
      'ok',false,'reason','unresolved_knockout_generation_chain');
  END IF;
  IF v_candidate.state<>'pending' THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','knockout_generation_state_mismatch',
      'player_state',v_player.status,'candidate_state',v_candidate.state);
  END IF;
  IF v_candidate.rebuy_prompt_until IS NOT NULL
     AND v_candidate.rebuy_prompt_until>clock_timestamp() THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','rebuy_decision_open',
      'rebuy_prompt_until',v_candidate.rebuy_prompt_until);
  END IF;

  PERFORM 1
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_eliminated_user_id AND s.left_at IS NULL
   ORDER BY s.id FOR UPDATE OF s;
  SELECT count(*) INTO v_live_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_eliminated_user_id AND s.left_at IS NULL;
  IF v_live_count>1 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','knockout_generation_has_multiple_live_seats');
  END IF;
  IF v_live_count=1 THEN
    SELECT s.* INTO v_live
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_eliminated_user_id AND s.left_at IS NULL;
    IF v_live.stack IS DISTINCT FROM 0
       OR v_live.table_id IS DISTINCT FROM v_candidate.table_id
       OR v_live.id IS DISTINCT FROM v_candidate.seat_id
       OR v_live.joined_at IS DISTINCT FROM v_candidate.seat_joined_at THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','knockout_generation_has_new_live_seat');
    END IF;
  END IF;

  v_result:=public.fn_claim_bounty_legacy_candidate_20260907(
    p_tournament_id,p_eliminated_user_id,p_position,p_prize,p_table_id,
    p_hand_id,p_hand_number,p_seat_joined_at,p_knocker_user_id,p_claimants,
    p_bubble_refund,p_allow_existing_eliminated);
  IF coalesce((v_result->>'ok')::boolean,false)
     AND coalesce((v_result->>'claimed')::boolean,false)
  THEN
    UPDATE public.tournament_knockout_candidates c
       SET state='eliminated',
           resolved_at=coalesce(c.resolved_at,clock_timestamp())
     WHERE c.id=v_candidate.id AND c.state='pending';
    GET DIAGNOSTICS v_changed=ROW_COUNT;
    IF v_changed<>1 THEN
      RAISE EXCEPTION
        'bounty knockout generation changed while claim committed'
        USING ERRCODE='serialization_failure';
    END IF;
  END IF;
  -- The proven older generations close with the bust that proved them.
  IF coalesce((v_result->>'ok')::boolean,false)
     AND coalesce((v_result->>'claimed')::boolean,false)
     AND cardinality(v_rebought_generations)>0 THEN
    UPDATE public.tournament_knockout_candidates c
       SET state='rebought',resolved_at=clock_timestamp()
     WHERE c.id=ANY(v_rebought_generations)
       AND c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_eliminated_user_id
       AND c.state='pending';
    GET DIAGNOSTICS v_changed=ROW_COUNT;
    IF v_changed<>cardinality(v_rebought_generations) THEN
      RAISE EXCEPTION
        'a bought-back knockout generation changed while the bounty claim committed'
        USING ERRCODE='serialization_failure';
    END IF;
    v_result:=v_result||jsonb_build_object(
      'rebought_generations',to_jsonb(v_rebought_generations));
  END IF;
  RETURN v_result;
END;
$function$;
ALTER FUNCTION public.fn_claim_tournament_bounty_elimination(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_claim_tournament_bounty_elimination(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_claim_tournament_bounty_elimination(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean) TO "postgres";
GRANT EXECUTE ON FUNCTION public.fn_claim_tournament_bounty_elimination(uuid,uuid,integer,numeric,uuid,uuid,bigint,timestamp with time zone,uuid,jsonb,numeric,boolean) TO "service_role";
DO $absent$ BEGIN IF to_regprocedure('public.fn_collect_bounty(uuid,uuid,uuid,jsonb)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_collect_bounty(uuid,uuid,uuid,jsonb)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_collect_bounty(p_tournament_id uuid, p_eliminated_user_id uuid, p_collector_user_id uuid, p_claimants jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  v_result jsonb;
  v_shares jsonb;
  v_paid_cash numeric;
  v_added_to_head numeric;
  v_context text := current_setting('app.bounty_obligation_id',true);
  v_prior_context text;
  v_obligation_count integer;
  v_pko_watermark bigint;
  v_predecessors jsonb;
  v_t record;
  v_elim record;
  v_head numeric;
  v_available numeric;
  v_payable numeric;
  v_cash numeric;
  v_to_head numeric;
  v_cents integer;
  v_cash_cents integer;
  v_mode text;
  v_funded boolean;
  v_claimants jsonb;
  v_n integer;
  v_total_weight numeric;
  v_paid_total numeric := 0;
  v_head_total numeric := 0;
  c record;
  v_share_cents integer;
  v_assigned_cents integer := 0;
  v_i integer := 0;
  v_prior numeric;
  v_settle jsonb;
  v_desc text;
  v_core_collector_user_id uuid;
  v_core_claimants jsonb;
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM 1 FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;

  IF COALESCE(v_context,'')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    SELECT * INTO o FROM public.tournament_bounty_obligations bo
     WHERE bo.id=v_context::uuid AND bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest'
     FOR UPDATE;
  ELSE
    SELECT count(*) INTO v_obligation_count
      FROM public.tournament_bounty_obligations bo
     WHERE bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest';
    IF v_obligation_count>1 THEN
      RETURN jsonb_build_object('ok',false,'reason','bounty_generation_identity_required');
    END IF;
    SELECT * INTO o FROM public.tournament_bounty_obligations bo
     WHERE bo.tournament_id=p_tournament_id
       AND bo.eliminated_user_id=p_eliminated_user_id
       AND bo.mode<>'mystery_chest'
     FOR UPDATE;
  END IF;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_obligation_not_ready');
  END IF;
  IF o.state='settled' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'user_id',b.collector_player_id,
             'cash',GREATEST(0,b.bounty_amount-COALESCE(b.added_to_collector_bounty,0)),
             'to_head',COALESCE(b.added_to_collector_bounty,0))
             ORDER BY b.collector_player_id),'[]'::jsonb),
           COALESCE(sum(GREATEST(0,b.bounty_amount-COALESCE(b.added_to_collector_bounty,0))),0),
           COALESCE(sum(b.added_to_collector_bounty),0)
      INTO v_shares,v_paid_cash,v_added_to_head
      FROM public.tournament_bounties b
     WHERE b.bounty_obligation_id=o.id;
    IF NOT public.fn_bounty_obligation_has_complete_marker(o.id) THEN
      RETURN jsonb_build_object('ok',false,'reason','settled_marker_incomplete',
                                'obligation_id',o.id);
    END IF;
    IF o.mode='pko' THEN
      INSERT INTO public.tournament_pko_settlement_watermarks
        (tournament_id,last_settled_hand_number,last_obligation_id)
      VALUES (o.tournament_id,o.hand_number,o.id)
      ON CONFLICT (tournament_id) DO UPDATE
        SET last_settled_hand_number=GREATEST(
              public.tournament_pko_settlement_watermarks.last_settled_hand_number,
              EXCLUDED.last_settled_hand_number),
            last_obligation_id=CASE
              WHEN EXCLUDED.last_settled_hand_number>=
                   public.tournament_pko_settlement_watermarks.last_settled_hand_number
              THEN EXCLUDED.last_obligation_id
              ELSE public.tournament_pko_settlement_watermarks.last_obligation_id END,
            updated_at=now();
    END IF;
    RETURN jsonb_build_object('ok',true,'already',true,'obligation_id',o.id,
      'marker_verified',true,'mode',o.mode,'head',o.head_amount,
      'paid_cash',v_paid_cash,'added_to_head',v_added_to_head,
      'split',jsonb_array_length(v_shares)>1,'shares',v_shares);
  END IF;

  IF o.mode='pko' THEN
    v_predecessors:=public.fn_pko_claim_predecessor_status_v1(
      o.tournament_id,o.eliminated_user_id,o.table_id,o.hand_id,
      o.hand_number,o.seat_joined_at);
    IF v_predecessors->>'ok' IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('ok',false,'reason','pko_predecessor_not_ready',
                               'predecessor_proof',v_predecessors);
    END IF;
  END IF;

  IF o.mode='pko' THEN
    SELECT w.last_settled_hand_number INTO v_pko_watermark
      FROM public.tournament_pko_settlement_watermarks w
     WHERE w.tournament_id=o.tournament_id FOR UPDATE;
    IF v_pko_watermark IS NOT NULL AND o.hand_number<v_pko_watermark THEN
      v_predecessors:=public.fn_pko_watermark_admission_status_v1(
        o.tournament_id,o.eliminated_user_id,o.table_id,o.hand_id,
        o.hand_number,o.seat_joined_at,o.claimants);
      IF v_predecessors->>'ok' IS DISTINCT FROM 'true' THEN
        RETURN jsonb_build_object('ok',false,'reason','pko_order_unproven',
          'watermark_proof',v_predecessors);
      END IF;
    END IF;
    -- The accepted-candidate guard above proves every actual incoming head
    -- dependency, including larger reserved hand numbers. Unrelated pending
    -- heads do not change this captured head and must not serialize its payout.
  END IF;

  -- Ignore caller ordering/weights. The exact pot-derived, roster-validated
  -- snapshot stored by the atomic claim is the only payout authority. The
  -- audited payer is inlined here so this root survives retirement of the
  -- temporary rolling-deployment body.
  v_core_collector_user_id := o.knocker_user_id;
  v_core_claimants := o.claimants;
  v_prior_context := current_setting('app.bounty_obligation_id',true);
  PERFORM set_config('app.bounty_obligation_id',o.id::text,true);

  <<collect_core>>
  BEGIN
    IF v_core_collector_user_id IS NULL OR p_eliminated_user_id IS NULL THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'missing_party');
      EXIT collect_core;
    END IF;

    SELECT id, is_bounty, is_pko, is_mystery_bounty, bounty_amount,
           bounty_pool, bounty_pool_paid, mystery_bounty_stage
      INTO v_t FROM tournaments WHERE id = p_tournament_id FOR UPDATE;
    IF NOT FOUND THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'tournament_not_found');
      EXIT collect_core;
    END IF;
    IF NOT (COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false)) THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'not_a_bounty_tournament');
      EXIT collect_core;
    END IF;

    IF COALESCE(v_t.is_pko, false) AND COALESCE(v_t.is_mystery_bounty, false) THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'undefined_pko_mystery_hybrid',
        'detail', 'PKO heads claim against bounty_pool; mystery chests are a sealed '
               || 'inventory. No split satisfies both. This event should not exist.');
      EXIT collect_core;
    END IF;

    /* A BUST BELONGS TO THE PHASE ITS HAND WAS PLAYED IN (2026-09-11). A
       persisted mystery_pre obligation is a head earned before activation;
       the seed keeps it outside the chest pool, so it is paid from the
       regular half after the chests open. Refusing it only strands it. */
    IF COALESCE(v_t.is_mystery_bounty, false)
       AND v_t.mystery_bounty_stage = 'active'
       AND o.mode IS DISTINCT FROM 'mystery_pre' THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'mystery_phase_active');
      EXIT collect_core;
    END IF;

    IF EXISTS (
      SELECT 1 FROM tournament_bounties b
       WHERE b.tournament_id = p_tournament_id
         AND b.eliminated_player_id = p_eliminated_user_id
         AND (
           b.bounty_obligation_id = (SELECT pending.id
             FROM tournament_bounty_obligations pending
            WHERE pending.tournament_id=p_tournament_id
              AND pending.eliminated_user_id=p_eliminated_user_id
              AND pending.mode <> 'mystery_chest' AND pending.state='pending'
            ORDER BY pending.hand_number, pending.created_at LIMIT 1)
           OR (b.bounty_obligation_id IS NULL AND NOT EXISTS (
             SELECT 1 FROM tournament_bounty_obligations pending
              WHERE pending.tournament_id=p_tournament_id
                AND pending.eliminated_user_id=p_eliminated_user_id
                AND pending.mode <> 'mystery_chest' AND pending.state='pending'))
         )
    ) THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'already_collected');
      EXIT collect_core;
    END IF;

    SELECT current_bounty INTO v_elim
      FROM tournament_players
     WHERE tournament_id = p_tournament_id AND user_id = p_eliminated_user_id
     FOR UPDATE;
    IF NOT FOUND THEN
      v_result := jsonb_build_object(
        'ok', false, 'reason', 'eliminated_player_not_in_tournament');
      EXIT collect_core;
    END IF;

    v_mode := CASE WHEN COALESCE(v_t.is_pko,false) THEN 'pko'
                   WHEN COALESCE(v_t.is_mystery_bounty,false) THEN 'mystery_pre'
                   ELSE 'regular' END;

    v_head := COALESCE(NULLIF(v_elim.current_bounty, 0), v_t.bounty_amount, 0);
    IF v_head <= 0 THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'no_head_value');
      EXIT collect_core;
    END IF;
    IF EXISTS (
      SELECT 1 FROM tournament_bounty_obligations pending
       WHERE pending.tournament_id=p_tournament_id
         AND pending.eliminated_user_id=p_eliminated_user_id
         AND pending.mode <> 'mystery_chest' AND pending.state='pending'
         AND pending.head_amount IS DISTINCT FROM round(v_head,2)
    ) THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'head_snapshot_changed');
      EXIT collect_core;
    END IF;

    v_funded := COALESCE(v_t.bounty_pool, 0) > 0;
    SELECT round(COALESCE(v_t.bounty_pool,0) - COALESCE(SUM(
             CASE WHEN lower(wt.type) = 'debit' THEN -abs(wt.amount)
                  ELSE wt.amount END), 0), 2)
      INTO v_available
      FROM wallet_transactions wt
     WHERE wt.related_entity_id = p_tournament_id
       AND wt.category = 'bounty';
    -- DIAMOND PHASE 9: a Diamond bounty is a ledger row, not a wallet row;
    -- the bank is what the entries put in less what it already paid.
    IF public.fn_poker_diamond_tournament(p_tournament_id) THEN
      SELECT e.bounty_balance INTO v_available
        FROM public.fn_poker_diamond_tournament_escrow(p_tournament_id) e;
    END IF;

    IF v_funded THEN
      IF v_available <= 0 THEN
        v_result := jsonb_build_object('ok', false, 'reason', 'bounty_pool_exhausted',
                                      'head', v_head, 'available', v_available);
        EXIT collect_core;
      END IF;
      IF v_available < v_head THEN
        v_result := jsonb_build_object('ok', false, 'reason', 'bounty_pool_underfunded',
                                      'head', v_head, 'available', v_available);
        EXIT collect_core;
      END IF;
      v_payable := v_head;
    ELSE
      v_payable := v_head;
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
             'user_id', x.uid, 'weight', x.w)), '[]'::jsonb)
      INTO v_claimants
      FROM (
        SELECT (e->>'user_id')::uuid AS uid, (e->>'weight')::numeric AS w
          FROM jsonb_array_elements(COALESCE(v_core_claimants, '[]'::jsonb)) e
         WHERE (e->>'user_id') IS NOT NULL
           AND COALESCE((e->>'weight')::numeric, 0) > 0
           AND EXISTS (
             SELECT 1 FROM tournament_players tp
              WHERE tp.tournament_id = p_tournament_id
                AND tp.user_id = (e->>'user_id')::uuid)
      ) x;
    v_n := jsonb_array_length(v_claimants);
    IF v_n <= 1 THEN
      v_claimants := jsonb_build_array(jsonb_build_object(
        'user_id', v_core_collector_user_id, 'weight', 1));
      v_n := 1;
    END IF;
    SELECT sum((e->>'weight')::numeric) INTO v_total_weight
      FROM jsonb_array_elements(v_claimants) e;

    v_cents := round(v_payable * 100)::integer;
    v_desc := CASE v_mode
      WHEN 'pko' THEN 'PKO bounty (cash half) from eliminated player'
      WHEN 'mystery_pre' THEN 'Bounty collected before the mystery phase opened'
      ELSE 'Bounty collected from eliminated player' END
      || CASE WHEN v_n > 1 THEN ' (split pot, ' || v_n || ' winners)' ELSE '' END;
    v_shares := '[]'::jsonb;

    FOR c IN
      SELECT (e->>'user_id')::uuid AS uid, (e->>'weight')::numeric AS w
        FROM jsonb_array_elements(v_claimants) e
       ORDER BY (e->>'weight')::numeric ASC, (e->>'user_id')
    LOOP
      v_i := v_i + 1;
      IF v_i < v_n THEN
        v_share_cents := floor(v_cents * c.w / v_total_weight)::integer;
        IF v_share_cents > 0 THEN
          v_share_cents := public.fn_ca_unit_floor_cents(
            v_share_cents::bigint,
            public.fn_ca_tournament_unit_cents(p_tournament_id))::integer;
        END IF;
      ELSE
        v_share_cents := v_cents - v_assigned_cents;
      END IF;
      v_assigned_cents := v_assigned_cents + v_share_cents;
      CONTINUE WHEN v_share_cents <= 0;

      IF v_mode = 'pko' THEN
        v_cash_cents := public.fn_ca_unit_floor_cents(
          (v_share_cents / 2)::bigint,
          public.fn_ca_tournament_unit_cents(p_tournament_id))::integer;
        v_cash := v_cash_cents / 100.0;
        v_to_head := (v_share_cents - v_cash_cents) / 100.0;
      ELSE
        v_cash := v_share_cents / 100.0;
        v_to_head := 0;
      END IF;

      IF v_cash > 0 THEN
        v_prior := COALESCE((
          SELECT debt.amount_paid FROM public.tournament_obligations debt
           WHERE debt.tournament_id = p_tournament_id
             AND debt.kind = 'bounty'
             AND debt.place IS NULL
             AND debt.user_id = c.uid), 0);
        v_settle := public.fn_settle_tournament_obligation(
          p_tournament_id, 'bounty', NULL, c.uid, round(v_prior + v_cash, 2),
          'fn_collect_bounty', v_desc);
        IF NOT COALESCE((v_settle->>'ok')::boolean, false) THEN
          RAISE EXCEPTION
            'fn_collect_bounty: bounty of % to % in tournament % refused (%); nothing recorded',
            v_cash, c.uid, p_tournament_id,
            COALESCE(v_settle->>'refused_reason', 'unknown');
        END IF;
        IF round(COALESCE((v_settle->>'paid')::numeric, 0), 2)
             <> round(v_cash, 2) THEN
          RAISE EXCEPTION
            'fn_collect_bounty: obligation paid % but the share is % for % in tournament %; nothing recorded',
            v_settle->>'paid', v_cash, c.uid, p_tournament_id;
        END IF;
      END IF;

      UPDATE tournament_players
         SET bounties_collected = COALESCE(bounties_collected,0) + 1,
             bounty_winnings = round(COALESCE(bounty_winnings,0) + v_cash, 2),
             current_bounty = round(COALESCE(current_bounty,0) + v_to_head, 2)
       WHERE tournament_id = p_tournament_id AND user_id = c.uid;

      INSERT INTO tournament_bounties
        (tournament_id, eliminated_player_id, collector_player_id, bounty_amount,
         added_to_collector_bounty, is_mystery_revealed)
      VALUES
        (p_tournament_id, p_eliminated_user_id, c.uid,
         round(v_share_cents / 100.0, 2),
         CASE WHEN v_to_head > 0 THEN v_to_head ELSE NULL END, false);

      v_paid_total := v_paid_total + v_cash;
      v_head_total := v_head_total + v_to_head;
      v_shares := v_shares || jsonb_build_object(
        'user_id', c.uid, 'cash', v_cash, 'to_head', v_to_head);
    END LOOP;

    UPDATE tournament_players SET current_bounty = 0
     WHERE tournament_id = p_tournament_id AND user_id = p_eliminated_user_id;

    IF v_funded THEN
      UPDATE tournaments
         SET bounty_pool_paid = round(COALESCE(bounty_pool_paid,0) + v_paid_total, 2)
       WHERE id = p_tournament_id;
    END IF;

    v_result := jsonb_build_object(
      'ok', true, 'mode', v_mode, 'funded', v_funded,
      'head', v_head, 'paid_cash', round(v_paid_total, 2),
      'added_to_head', round(v_head_total, 2),
      'split', v_n > 1, 'shares', v_shares,
      'capped', v_funded AND v_payable < v_head,
      'pool_remaining', CASE WHEN v_funded
                             THEN round(v_available - v_paid_total, 2) END);
  END collect_core;

  PERFORM set_config('app.bounty_obligation_id',COALESCE(v_prior_context,''),true);

  IF NOT COALESCE((v_result->>'ok')::boolean,false) THEN
    -- A semantic pre-write refusal is safe to commit and stays pending. Any
    -- accepted payer result below must satisfy the exact marker postcondition
    -- or raise so its wallet/head/counter mutations roll back atomically.
    RETURN v_result || jsonb_build_object('obligation_id',o.id);
  END IF;

  UPDATE public.tournament_bounty_obligations bo
     SET state='settled',settled_at=COALESCE(settled_at,now()),last_error=NULL
   WHERE bo.id=o.id AND bo.state='pending'
     AND public.fn_bounty_obligation_has_complete_marker(bo.id);
  IF NOT public.fn_bounty_obligation_has_complete_marker(o.id)
     OR NOT EXISTS (SELECT 1 FROM public.tournament_bounty_obligations bo
                     WHERE bo.id=o.id AND bo.state='settled') THEN
    RAISE EXCEPTION 'accepted bounty payout did not produce the exact settled marker for %',o.id
      USING ERRCODE='check_violation';
  END IF;
  IF o.mode='pko' THEN
    INSERT INTO public.tournament_pko_settlement_watermarks
      (tournament_id,last_settled_hand_number,last_obligation_id)
    VALUES (o.tournament_id,o.hand_number,o.id)
    ON CONFLICT (tournament_id) DO UPDATE
      SET last_settled_hand_number=GREATEST(
            public.tournament_pko_settlement_watermarks.last_settled_hand_number,
            EXCLUDED.last_settled_hand_number),
          last_obligation_id=CASE
            WHEN EXCLUDED.last_settled_hand_number>=
                 public.tournament_pko_settlement_watermarks.last_settled_hand_number
            THEN EXCLUDED.last_obligation_id
            ELSE public.tournament_pko_settlement_watermarks.last_obligation_id END,
          updated_at=now();
  END IF;
  RETURN v_result || jsonb_build_object('obligation_id',o.id,'marker_verified',true);
END;
$function$;
ALTER FUNCTION public.fn_collect_bounty(uuid,uuid,uuid,jsonb) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_collect_bounty(uuid,uuid,uuid,jsonb) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_collect_bounty(uuid,uuid,uuid,jsonb) TO "postgres";
GRANT EXECUTE ON FUNCTION public.fn_collect_bounty(uuid,uuid,uuid,jsonb) TO "service_role";
DO $absent$ BEGIN IF to_regprocedure('public.fn_eliminate_player_legacy_candidate_20260907(uuid,uuid,integer,numeric,numeric)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_eliminate_player_legacy_candidate_20260907(uuid,uuid,integer,numeric,numeric)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_eliminate_player_legacy_candidate_20260907(p_tournament_id uuid, p_user_id uuid, p_position integer, p_prize numeric, p_bubble_refund numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_p public.tournament_players%ROWTYPE;
  v_changed integer;
  v_released_tables uuid[] := ARRAY[]::uuid[];
  v_bust_at timestamptz;
  v_bust_hand bigint;
  v_bust_captured_at timestamptz;
  v_resolved_candidate_id uuid;
BEGIN
  IF p_position < 2 OR p_prize IS NULL OR p_prize < 0
     OR p_bubble_refund IS NULL OR p_bubble_refund < 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_place_or_prize');
  END IF;
  IF p_bubble_refund <> 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','bubble_refund_requires_finalized_batch');
  END IF;
  SELECT * INTO v_t FROM public.tournaments WHERE id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;
  IF v_t.status <> 'RUNNING' THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_running');
  END IF;
  IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
     OR COALESCE(v_t.is_mystery_bounty,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_requires_outbox_claim');
  END IF;
  SELECT * INTO v_p FROM public.tournament_players
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','player_not_found'); END IF;
  IF v_p.status = 'winner' THEN
    RETURN jsonb_build_object('ok',false,'reason','player_is_winner');
  END IF;
  IF v_p.status = 'eliminated' THEN
    IF v_p.position IS DISTINCT FROM p_position
       OR round(COALESCE(v_p.prize,0),2) <> round(p_prize,2) THEN
      RETURN jsonb_build_object('ok',false,'reason','elimination_identity_conflict');
    END IF;
    RETURN jsonb_build_object('ok',true,'already',true,'position',v_p.position,'prize',v_p.prize);
  END IF;
  IF v_p.status <> 'playing' OR COALESCE(v_p.chips,0) > 0 THEN
    RETURN jsonb_build_object('ok',false,'reason','not_busted');
  END IF;
  /* A BUST IS RANKED BY WHEN IT HAPPENED (2026-09-11). eliminated_at was
     now(), the moment the door ACCEPTED a bust, so a bust the door refused
     for a while - an orphaned generation, a stale seat - was stamped later
     than busts that came after it. It is now the time of the bust: the
     commit time of the accepted hand of the generation the calling door has
     just bound and proved (the latest committed zero-stack generation), plus
     one microsecond per earlier rank in that hand - smaller hand-start stack
     first (it busts first and finishes lower), then user id. That is the
     rule fn_settle_tournament_places ranks places by: busts in different
     hands are ordered by those hands' commit times. A bust whose hand cannot
     be read is refused, never stamped with the clock; so is a generation the
     player provably played on from - a posted rebuy leg after it AND a later
     hand of this event that deals the player in - since its hand is then not
     the bust and nothing here can say which one is. */
  v_resolved_candidate_id:=public.fn_ca_latest_committed_knockout_candidate(
    p_tournament_id,p_user_id);
  SELECT a.committed_at
         + (SELECT count(*)
              FROM public.tournament_knockout_candidates s
             WHERE s.tournament_id=c.tournament_id
               AND s.table_id=c.table_id
               AND s.hand_number=c.hand_number
               AND s.hand_id=c.hand_id
               AND (s.stack_before,s.eliminated_user_id)
                   <(c.stack_before,c.eliminated_user_id))::integer
           * interval '1 microsecond',
         c.hand_number,c.created_at
    INTO v_bust_at,v_bust_hand,v_bust_captured_at
    FROM public.tournament_knockout_candidates c
    JOIN public.hand_atomic_commits a
      ON a.table_id=c.table_id
     AND a.hand_number=c.hand_number
     AND a.hand_id=c.hand_id
   WHERE c.id=v_resolved_candidate_id
     AND c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
     AND c.state='pending';
  IF v_bust_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','knockout_bust_time_unproven');
  END IF;
  IF EXISTS (
       SELECT 1 FROM public.chip_ledger l
        WHERE l.from_entity_id=p_user_id
          AND l.tournament_id=p_tournament_id
          AND l.category='rebuy'
          AND l.from_type='player_wallet'
          AND l.to_type='prize_liability'
          AND l.status='posted'
          AND l.amount>0
          AND l.created_at>v_bust_captured_at)
     AND EXISTS (
       SELECT 1 FROM public.hand_history h
        WHERE h.tournament_id=p_tournament_id
          AND h.hand_number>v_bust_hand
          AND (h.players @> jsonb_build_array(jsonb_build_object(
                 'userId',p_user_id::text))
               OR h.players @> jsonb_build_array(jsonb_build_object(
                 'user_id',p_user_id::text)))) THEN
    /* Nothing newer can bind this player, who stays 'playing' at zero
       chips, so this refusal would hold the event open for ever without a
       word. It is written where the money board reads - once: one open alert
       per player. */
    INSERT INTO public.financial_alerts(severity,source,message,context)
    SELECT 'critical','knockout_door.payout_blocked_by_unrecordable_bust',
      'A busted player cannot be recorded, so the tournament cannot finish: '
        ||'the only knockout generation left to record them by is one they '
        ||'rebought from and played on after, and no later bust was captured. '
        ||'Their place needs a ruling from their last hand.',
      jsonb_build_object('tournament_id',p_tournament_id,'user_id',p_user_id,
        'reason','knockout_bust_time_unproven',
        'detail','played_on_after_a_rebuy','hand_number',v_bust_hand)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source='knockout_door.payout_blocked_by_unrecordable_bust'
          AND NOT fa.resolved
          AND fa.context->>'tournament_id'=p_tournament_id::text
          AND fa.context->>'user_id'=p_user_id::text);
    RETURN jsonb_build_object('ok',false,'reason','knockout_bust_time_unproven',
                              'detail','played_on_after_a_rebuy');
  END IF;
  UPDATE public.tournament_players
     SET status='eliminated',position=p_position,prize=round(p_prize,2),eliminated_at=v_bust_at
   WHERE tournament_id=p_tournament_id AND user_id=p_user_id
     AND status='playing' AND COALESCE(chips,0)<=0;
  GET DIAGNOSTICS v_changed=ROW_COUNT;
  IF v_changed <> 1 THEN
    RAISE EXCEPTION 'zero-stack elimination CAS changed % rows',v_changed
      USING ERRCODE='serialization_failure';
  END IF;

  WITH released AS (
    UPDATE public.table_seats s SET left_at=now()
      FROM public.tables tb
     WHERE tb.id=s.table_id AND tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL
    RETURNING s.table_id
  ) SELECT COALESCE(array_agg(DISTINCT table_id),ARRAY[]::uuid[])
      INTO v_released_tables FROM released;
  UPDATE public.tables tb SET current_players=(
    SELECT count(*) FROM public.table_seats s WHERE s.table_id=tb.id AND s.left_at IS NULL)
   WHERE tb.id=ANY(v_released_tables);
  PERFORM public.fn_sync_seat_first_player_count(p_tournament_id);

  RETURN jsonb_build_object('ok',true,'claimed',true,'position',p_position,
                            'prize',round(p_prize,2),'bubble_refund',0);
END;
$function$;
ALTER FUNCTION public.fn_eliminate_player_legacy_candidate_20260907(uuid,uuid,integer,numeric,numeric) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_eliminate_player_legacy_candidate_20260907(uuid,uuid,integer,numeric,numeric) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_eliminate_player_legacy_candidate_20260907(uuid,uuid,integer,numeric,numeric) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_eliminate_tournament_player_atomic(uuid,uuid,integer,numeric,numeric)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_eliminate_tournament_player_atomic(uuid,uuid,integer,numeric,numeric)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_eliminate_tournament_player_atomic(p_tournament_id uuid, p_user_id uuid, p_position integer, p_prize numeric, p_bubble_refund numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_resolved_candidate_id uuid;
  v_atomic public.hand_atomic_commits%ROWTYPE;
  v_live public.table_seats%ROWTYPE;
  v_evidence_stack numeric;
  v_settlement_hand_text text;
  v_settlement_hand_id uuid;
  v_live_count integer;
  v_changed integer;
  v_result jsonb;
  v_rebought_generations uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_position IS NULL OR p_position<2 OR p_prize IS NULL OR p_prize<0
     OR p_bubble_refund IS NULL OR p_bubble_refund<0 THEN
    RETURN jsonb_build_object('ok',false,'reason','invalid_place_or_prize');
  END IF;
  IF p_bubble_refund<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','bubble_refund_requires_finalized_batch');
  END IF;

  SELECT * INTO v_t FROM public.tournaments t
   WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_found');
  END IF;
  IF v_t.status<>'RUNNING' THEN
    RETURN jsonb_build_object('ok',false,'reason','tournament_not_running');
  END IF;
  IF coalesce(v_t.is_bounty,false) OR coalesce(v_t.is_pko,false)
     OR coalesce(v_t.is_mystery_bounty,false) THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_requires_outbox_claim');
  END IF;

  SELECT * INTO v_player FROM public.tournament_players tp
   WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','player_not_found');
  END IF;
  IF v_player.status='winner' THEN
    RETURN jsonb_build_object('ok',false,'reason','player_is_winner');
  END IF;
  IF v_player.status NOT IN ('playing','eliminated')
     OR (v_player.status='playing' AND coalesce(v_player.chips,0)>0) THEN
    RETURN jsonb_build_object('ok',false,'reason','not_busted');
  END IF;

  PERFORM 1
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
   ORDER BY c.hand_number,c.id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','knockout_candidate_required');
  END IF;

  -- The owner-only resolver selects this player's latest immutable entry
  -- generation and already proves both durable halves of its accepted hand.
  -- Re-read every identity here so this transaction is independently bound to
  -- candidate(history hand) -> atomic(internal settlement hand) -> receipt.
  v_resolved_candidate_id:=public.fn_ca_latest_committed_knockout_candidate(
    p_tournament_id,p_user_id);
  SELECT c.* INTO v_candidate
    FROM public.tournament_knockout_candidates c
   WHERE c.id=v_resolved_candidate_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','committed_knockout_candidate_not_found');
  END IF;

  SELECT a.* INTO v_atomic
    FROM public.hand_atomic_commits a
   WHERE a.table_id=v_candidate.table_id
     AND a.hand_number=v_candidate.hand_number
     AND a.hand_id=v_candidate.hand_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_candidate_missing');
  END IF;
  v_settlement_hand_text:=v_atomic.stack_result->>'hand_id';
  -- The settlement owner uses md5(... )::uuid for its stable internal key;
  -- validate PostgreSQL's canonical UUID shape without inventing RFC nibbles.
  IF coalesce(v_settlement_hand_text,'')
       !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_atomic.stack_result->>'table_id'<>v_candidate.table_id::text
     OR coalesce(v_atomic.stack_result->>'hand_number','')
          !~ '^[0-9]+$'
     OR (v_atomic.stack_result->>'hand_number')::bigint<>
          v_candidate.hand_number
     OR coalesce(v_atomic.stack_result->'written'->>p_user_id::text,'')
          !~ '^-?[0-9]+([.][0-9]+)?$'
     OR (v_atomic.stack_result->'written'->>p_user_id::text)::numeric<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','atomic_knockout_candidate_identity_conflict');
  END IF;
  v_settlement_hand_id:=v_settlement_hand_text::uuid;

  SELECT (k.result->'written'->>p_user_id::text)::numeric
    INTO v_evidence_stack
    FROM public.settlement_idempotency_keys k
   WHERE k.table_id=v_candidate.table_id
     AND k.hand_id=v_settlement_hand_id
     AND k.status='succeeded'
     AND k.completed_at IS NOT NULL
     AND k.result->>'table_id'=v_candidate.table_id::text
     AND coalesce(k.result->>'hand_number','') ~ '^[0-9]+$'
     AND (k.result->>'hand_number')::bigint=v_candidate.hand_number
     AND coalesce(k.result->'written'->>p_user_id::text,'')
           ~ '^-?[0-9]+([.][0-9]+)?$';
  IF NOT FOUND OR v_evidence_stack<>0 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','exact_knockout_settlement_receipt_missing');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_user_id
       AND c.hand_number>v_candidate.hand_number
  ) THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','latest_knockout_evidence_chain_conflict');
  END IF;
  /* A GENERATION A REBUY PAID FOR IS NOT A LIVE BUST (2026-09-11).
     The 2026-09-08/09 rebuy chain bought players back in without marking the
     busted generation 'rebought', so each left an older 'pending' row, and
     this check then refused every later, real bust of the same player for
     ever. A pending generation is proven bought back - not a bust anybody still
     owes a place - when a posted 'rebuy' leg moved this player's own wallet
     into this event's prize liability AFTER that generation was captured and
     BEFORE the player's next generation was: the chips busted at the next
     hand are the chips that leg paid for. Only such rows are resolved to
     'rebought', and only in the transaction that records the newer bust. A
     leg outside that window proves nothing, a generation in any other state
     is not touched, and anything unproven is refused exactly as before. */
  SELECT COALESCE(array_agg(c.id ORDER BY c.hand_number,c.id),ARRAY[]::uuid[])
    INTO v_rebought_generations
    FROM public.tournament_knockout_candidates c
   WHERE c.tournament_id=p_tournament_id
     AND c.eliminated_user_id=p_user_id
     AND c.hand_number<v_candidate.hand_number
     AND c.state='pending'
     AND (
       -- DIAMOND PHASE 8: a Diamond rebuy or re-entry is a Diamond ledger
       -- row, not a chip leg; it proves the generation the same way.
       EXISTS (
       SELECT 1 FROM public.poker_diamond_tournament_ledger d
        WHERE d.user_id=p_user_id
          AND d.tournament_id=p_tournament_id
          AND d.kind IN ('rebuy','reentry')
          AND d.amount>0
          AND d.created_at>c.created_at
          AND d.created_at<(
            SELECT n.created_at
              FROM public.tournament_knockout_candidates n
             WHERE n.tournament_id=p_tournament_id
               AND n.eliminated_user_id=p_user_id
               AND n.hand_number>c.hand_number
             ORDER BY n.hand_number,n.id
             LIMIT 1))
       OR EXISTS (
       SELECT 1 FROM public.chip_ledger l
        WHERE l.from_entity_id=p_user_id
          AND l.tournament_id=p_tournament_id
          AND l.category='rebuy'
          AND l.from_type='player_wallet'
          AND l.to_type='prize_liability'
          AND l.status='posted'
          AND l.amount>0
          AND l.created_at>c.created_at
          AND l.created_at<(
            SELECT n.created_at
              FROM public.tournament_knockout_candidates n
             WHERE n.tournament_id=p_tournament_id
               AND n.eliminated_user_id=p_user_id
               AND n.hand_number>c.hand_number
             ORDER BY n.hand_number,n.id
             LIMIT 1)));
  IF EXISTS (
    SELECT 1 FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_user_id
       AND c.hand_number<v_candidate.hand_number
       AND c.state<>'rebought'
       AND c.id<>ALL(v_rebought_generations)
  ) THEN
    /* This refusal cannot clear by itself - no newer generation will make
       the older one proven - so it would hold the event open for ever
       without a word. It is written where the money board reads - once: one
       open alert per player. */
    INSERT INTO public.financial_alerts(severity,source,message,context)
    SELECT 'critical','knockout_door.payout_blocked_by_unrecordable_bust',
      'A busted player cannot be recorded, so the tournament cannot finish: '
        ||'an older knockout generation of theirs is neither rebought nor '
        ||'proven bought back (a posted rebuy leg after it and, in a bounty '
        ||'event, its head collected). That generation needs a ruling.',
      jsonb_build_object('tournament_id',p_tournament_id,'user_id',p_user_id,
        'reason','unresolved_knockout_generation_chain',
        'hand_number',v_candidate.hand_number)
     WHERE NOT EXISTS (
       SELECT 1 FROM public.financial_alerts fa
        WHERE fa.source='knockout_door.payout_blocked_by_unrecordable_bust'
          AND NOT fa.resolved
          AND fa.context->>'tournament_id'=p_tournament_id::text
          AND fa.context->>'user_id'=p_user_id::text);
    RETURN jsonb_build_object(
      'ok',false,'reason','unresolved_knockout_generation_chain');
  END IF;

  IF (v_player.status='playing' AND v_candidate.state<>'pending')
     OR (v_player.status='eliminated' AND v_candidate.state<>'eliminated') THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','knockout_generation_state_mismatch',
      'player_state',v_player.status,'candidate_state',v_candidate.state);
  END IF;
  IF v_candidate.state='pending'
     AND v_candidate.rebuy_prompt_until IS NOT NULL
     AND v_candidate.rebuy_prompt_until>clock_timestamp() THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','rebuy_decision_open',
      'rebuy_prompt_until',v_candidate.rebuy_prompt_until);
  END IF;

  PERFORM 1
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL
   ORDER BY s.id FOR UPDATE OF s;
  SELECT count(*) INTO v_live_count
    FROM public.table_seats s
    JOIN public.tables tb ON tb.id=s.table_id
   WHERE tb.tournament_id=p_tournament_id
     AND s.user_id=p_user_id AND s.left_at IS NULL;
  IF v_live_count>1 THEN
    RETURN jsonb_build_object(
      'ok',false,'reason','knockout_generation_has_multiple_live_seats');
  END IF;
  IF v_live_count=1 THEN
    SELECT s.* INTO v_live
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL;
    IF v_live.stack IS DISTINCT FROM 0
       OR v_live.table_id IS DISTINCT FROM v_candidate.table_id
       OR v_live.id IS DISTINCT FROM v_candidate.seat_id
       OR v_live.joined_at IS DISTINCT FROM v_candidate.seat_joined_at THEN
      RETURN jsonb_build_object(
        'ok',false,'reason','knockout_generation_has_new_live_seat');
    END IF;
  END IF;

  v_result:=public.fn_eliminate_player_legacy_candidate_20260907(
    p_tournament_id,p_user_id,p_position,p_prize,p_bubble_refund);
  IF coalesce((v_result->>'ok')::boolean,false)
     AND v_player.status='playing' THEN
    UPDATE public.tournament_knockout_candidates c
       SET state='eliminated',
           resolved_at=coalesce(c.resolved_at,clock_timestamp())
     WHERE c.id=v_candidate.id AND c.state='pending';
    GET DIAGNOSTICS v_changed=ROW_COUNT;
    IF v_changed<>1 THEN
      RAISE EXCEPTION 'knockout generation changed while elimination committed'
        USING ERRCODE='serialization_failure';
    END IF;
  END IF;
  -- The proven older generations close with the bust that proved them.
  IF coalesce((v_result->>'ok')::boolean,false)
     AND cardinality(v_rebought_generations)>0 THEN
    UPDATE public.tournament_knockout_candidates c
       SET state='rebought',resolved_at=clock_timestamp()
     WHERE c.id=ANY(v_rebought_generations)
       AND c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_user_id
       AND c.state='pending';
    GET DIAGNOSTICS v_changed=ROW_COUNT;
    IF v_changed<>cardinality(v_rebought_generations) THEN
      RAISE EXCEPTION 'a bought-back knockout generation changed while elimination committed'
        USING ERRCODE='serialization_failure';
    END IF;
    v_result:=v_result||jsonb_build_object(
      'rebought_generations',to_jsonb(v_rebought_generations));
  END IF;
  RETURN v_result;
END;
$function$;
ALTER FUNCTION public.fn_eliminate_tournament_player_atomic(uuid,uuid,integer,numeric,numeric) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_eliminate_tournament_player_atomic(uuid,uuid,integer,numeric,numeric) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_eliminate_tournament_player_atomic(uuid,uuid,integer,numeric,numeric) TO "postgres";
GRANT EXECUTE ON FUNCTION public.fn_eliminate_tournament_player_atomic(uuid,uuid,integer,numeric,numeric) TO "service_role";
DO $absent$ BEGIN IF to_regprocedure('public.fn_mystery_bounty_reserve(uuid,uuid,jsonb,uuid,text,uuid,integer)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_mystery_bounty_reserve(uuid,uuid,jsonb,uuid,text,uuid,integer)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_mystery_bounty_reserve(p_tournament_id uuid, p_eliminated_user_id uuid, p_recipients jsonb, p_table_id uuid, p_hand_id text, p_op_id uuid, p_reveal_ms integer DEFAULT 20000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  v_recipients jsonb;
  v_result jsonb;
  v_op_hex text;
  v_op_id uuid;
  v_prior_context text;
  v_stage text;
  v_existing record;
  v_chest record;
  v_award_id uuid;
  v_revealer uuid;
  v_idx integer;
  v_total integer;
  v_n integer;
  v_unit integer := public.fn_ca_tournament_unit_cents(p_tournament_id);  -- DIAMOND PHASE 9
BEGIN
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM 1 FROM public.tournaments t WHERE t.id=p_tournament_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','tournament_not_found'); END IF;
  SELECT * INTO o FROM public.tournament_bounty_obligations bo
   WHERE bo.tournament_id=p_tournament_id
     AND bo.eliminated_user_id=p_eliminated_user_id
     AND bo.mode='mystery_chest'
     AND bo.table_id=p_table_id AND bo.hand_id::text=p_hand_id
   ORDER BY bo.hand_number DESC LIMIT 1 FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_obligation_not_ready');
  END IF;

  SELECT jsonb_agg(jsonb_build_object(
           'user_id',e->>'user_id','weight',1,
           'is_designated_revealer',(e->>'user_id')::uuid=o.knocker_user_id)
           ORDER BY e->>'user_id')
    INTO v_recipients FROM jsonb_array_elements(o.claimants) e;
  v_op_hex := md5('mb:'||o.id::text);
  v_op_id := (substr(v_op_hex,1,8)||'-'||substr(v_op_hex,9,4)||'-4'||substr(v_op_hex,14,3)
    ||'-8'||substr(v_op_hex,18,3)||'-'||substr(v_op_hex,21,12))::uuid;
  v_prior_context := current_setting('app.bounty_obligation_id',true);
  PERFORM set_config('app.bounty_obligation_id',o.id::text,true);

  -- Inline the CSPRNG inventory reservation and exact-cent split. The
  -- generation-bound obligation remains the only source of recipient truth,
  -- while the rolling helper can be retired without breaking this root.
  <<mystery_reserve_core>>
  BEGIN
    IF p_eliminated_user_id IS NULL OR v_op_id IS NULL THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'missing_party');
      EXIT mystery_reserve_core;
    END IF;

    SELECT id, status, table_id
      INTO v_existing
      FROM public.tournament_bounty_awards
     WHERE op_id = v_op_id
        OR (
          tournament_id = p_tournament_id
          AND eliminated_user_id = p_eliminated_user_id
          AND (
            bounty_obligation_id = (
              SELECT pending.id
                FROM tournament_bounty_obligations pending
               WHERE pending.tournament_id=p_tournament_id
                 AND pending.eliminated_user_id=p_eliminated_user_id
                 AND pending.mode='mystery_chest'
                 AND pending.hand_id::text=p_hand_id
               ORDER BY pending.created_at DESC
               LIMIT 1)
            OR (bounty_obligation_id IS NULL AND NOT EXISTS (
              SELECT 1 FROM tournament_bounty_obligations pending
               WHERE pending.tournament_id=p_tournament_id
                 AND pending.eliminated_user_id=p_eliminated_user_id
                 AND pending.mode='mystery_chest'
                 AND pending.hand_id::text=p_hand_id))))
     LIMIT 1;

    IF FOUND THEN
      SELECT count(*) INTO v_total
        FROM public.tournament_bounty_awards a
       WHERE a.tournament_id = p_tournament_id
         AND a.table_id IS NOT DISTINCT FROM v_existing.table_id
         AND a.status IN ('reserved','revealed');
      SELECT count(*) INTO v_idx
        FROM public.tournament_bounty_awards a
       WHERE a.tournament_id = p_tournament_id
         AND a.table_id IS NOT DISTINCT FROM v_existing.table_id
         AND a.status IN ('reserved','revealed')
         AND a.reserved_at <= (
           SELECT reserved_at FROM public.tournament_bounty_awards
            WHERE id = v_existing.id);
      SELECT user_id INTO v_revealer
        FROM public.tournament_bounty_award_recipients
       WHERE award_id = v_existing.id
         AND is_designated_revealer
       LIMIT 1;
      v_result := jsonb_build_object(
        'ok', true, 'already', true, 'award_id', v_existing.id,
        'status', v_existing.status,
        'queue_index', GREATEST(v_idx, 1),
        'queue_total', GREATEST(v_total, 1),
        'designated_revealer', v_revealer,
        'recipient_user_ids', COALESCE((
          SELECT jsonb_agg(user_id)
            FROM public.tournament_bounty_award_recipients
           WHERE award_id = v_existing.id), '[]'::jsonb));
      EXIT mystery_reserve_core;
    END IF;

    SELECT mystery_bounty_stage INTO v_stage
      FROM public.tournaments
     WHERE id = p_tournament_id;
    IF v_stage IS DISTINCT FROM 'active' THEN
      v_result := jsonb_build_object(
        'ok', false, 'reason', 'mystery_phase_not_active', 'stage', v_stage);
      EXIT mystery_reserve_core;
    END IF;

    IF v_recipients IS NULL OR jsonb_typeof(v_recipients) <> 'array'
       OR jsonb_array_length(v_recipients) = 0 THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'no_recipients');
      EXIT mystery_reserve_core;
    END IF;

    UPDATE public.tournament_bounty_chests
       SET status = 'reserved'
     WHERE id = (
       SELECT id FROM public.tournament_bounty_chests
        WHERE tournament_id = p_tournament_id
          AND status = 'available'
        ORDER BY seq
        LIMIT 1
        FOR UPDATE SKIP LOCKED)
    RETURNING id, tier, amount_cents INTO v_chest;

    IF NOT FOUND THEN
      v_result := jsonb_build_object(
        'ok', false, 'reason', 'inventory_exhausted');
      EXIT mystery_reserve_core;
    END IF;

    INSERT INTO public.tournament_bounty_awards
      (tournament_id, chest_id, table_id, hand_id, eliminated_user_id,
       amount_cents, tier, status, op_id, reveal_deadline_at)
    VALUES
      (p_tournament_id, v_chest.id, p_table_id, p_hand_id,
       p_eliminated_user_id, v_chest.amount_cents, v_chest.tier,
       'reserved', v_op_id,
       now() + make_interval(
         secs => GREATEST(1, COALESCE(p_reveal_ms, 20000)) / 1000.0))
    RETURNING id INTO v_award_id;

    UPDATE public.tournament_bounty_chests
       SET award_id = v_award_id
     WHERE id = v_chest.id;

    WITH raw AS (
      SELECT (r->>'user_id')::uuid AS user_id,
             GREATEST(0, COALESCE((r->>'weight')::numeric, 0)) AS weight,
             COALESCE(
               (r->>'is_designated_revealer')::boolean, false) AS flagged
        FROM jsonb_array_elements(v_recipients) r
       WHERE (r->>'user_id') IS NOT NULL
    ),
    dedup AS (
      SELECT user_id, sum(weight) AS weight, bool_or(flagged) AS flagged
        FROM raw
       GROUP BY user_id
    ),
    norm AS (
      SELECT user_id,
             CASE WHEN (SELECT sum(weight) FROM dedup) > 0
                  THEN weight ELSE 1 END AS weight,
             flagged
        FROM dedup
    ),
    alloc AS (
      SELECT n.user_id, n.weight,
             public.fn_ca_unit_floor_cents(floor(v_chest.amount_cents * n.weight / t.w)::bigint, v_unit)::bigint AS fl,
             (v_chest.amount_cents * n.weight / t.w)
               - floor(v_chest.amount_cents * n.weight / t.w) AS frac
        FROM norm n
        CROSS JOIN (SELECT sum(weight) AS w FROM norm) t
    ),
    ranked AS (
      SELECT a.*,
             row_number() OVER (
               ORDER BY CASE WHEN v_unit = 1 THEN a.frac ELSE 0 END DESC,
                        CASE WHEN v_unit = 1 THEN a.weight ELSE 0 END DESC, a.user_id) AS rn,
             (SELECT v_chest.amount_cents - COALESCE(sum(fl), 0)
                FROM alloc) AS leftover
        FROM alloc a
    )
    INSERT INTO public.tournament_bounty_award_recipients
      (award_id, user_id, amount_cents, is_designated_revealer)
    SELECT v_award_id, user_id,
           fl + CASE WHEN v_unit = 1 THEN (CASE WHEN rn <= leftover THEN 1 ELSE 0 END)
                    WHEN rn = 1 THEN leftover ELSE 0 END,
           false
      FROM ranked
    ON CONFLICT (award_id, user_id) DO NOTHING;

    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n = 0 THEN
      v_result := jsonb_build_object('ok', false, 'reason', 'no_recipients');
      EXIT mystery_reserve_core;
    END IF;

    SELECT user_id INTO v_revealer
      FROM (
        SELECT (r->>'user_id')::uuid AS user_id,
               GREATEST(0, COALESCE((r->>'weight')::numeric, 0)) AS weight,
               COALESCE(
                 (r->>'is_designated_revealer')::boolean, false) AS flagged
          FROM jsonb_array_elements(v_recipients) r
         WHERE (r->>'user_id') IS NOT NULL
      ) q
     ORDER BY q.flagged DESC, q.weight DESC, q.user_id
     LIMIT 1;

    UPDATE public.tournament_bounty_award_recipients
       SET is_designated_revealer = (user_id = v_revealer)
     WHERE award_id = v_award_id;

    PERFORM 1 FROM public.tournament_bounty_award_recipients
     WHERE award_id = v_award_id
    HAVING sum(amount_cents) = v_chest.amount_cents;
    IF NOT FOUND THEN
      RAISE EXCEPTION
        'mystery bounty split lost money on award %', v_award_id;
    END IF;

    SELECT count(*) INTO v_total
      FROM public.tournament_bounty_awards a
     WHERE a.tournament_id = p_tournament_id
       AND a.table_id IS NOT DISTINCT FROM p_table_id
       AND a.status IN ('reserved','revealed');
    v_idx := v_total;

    v_result := jsonb_build_object(
      'ok', true, 'already', false, 'award_id', v_award_id,
      'queue_index', GREATEST(v_idx, 1),
      'queue_total', GREATEST(v_total, 1),
      'designated_revealer', v_revealer,
      'reveal_deadline_ms', GREATEST(1, COALESCE(p_reveal_ms, 20000)),
      'recipient_user_ids', COALESCE((
        SELECT jsonb_agg(user_id)
          FROM public.tournament_bounty_award_recipients
         WHERE award_id = v_award_id), '[]'::jsonb));
  END mystery_reserve_core;

  PERFORM set_config('app.bounty_obligation_id',COALESCE(v_prior_context,''),true);
  IF NOT COALESCE((v_result->>'ok')::boolean,false) THEN RETURN v_result; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournament_bounty_awards a
     WHERE a.id=(v_result->>'award_id')::uuid AND a.bounty_obligation_id=o.id
       AND NOT EXISTS (
         SELECT 1 FROM jsonb_array_elements(o.claimants) c
          WHERE NOT EXISTS (SELECT 1 FROM public.tournament_bounty_award_recipients r
                             WHERE r.award_id=a.id
                               AND r.user_id=(c->>'user_id')::uuid)
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_award_recipients r
          WHERE r.award_id=a.id
            AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(o.claimants) c
                             WHERE (c->>'user_id')::uuid=r.user_id)
       )
  ) THEN
    RAISE EXCEPTION 'mystery award recipients do not match obligation %',o.id;
  END IF;
  RETURN v_result || jsonb_build_object('obligation_id',o.id,'recipients_verified',true);
END;
$function$;
ALTER FUNCTION public.fn_mystery_bounty_reserve(uuid,uuid,jsonb,uuid,text,uuid,integer) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_mystery_bounty_reserve(uuid,uuid,jsonb,uuid,text,uuid,integer) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_mystery_bounty_reserve(uuid,uuid,jsonb,uuid,text,uuid,integer) TO "postgres";
GRANT EXECUTE ON FUNCTION public.fn_mystery_bounty_reserve(uuid,uuid,jsonb,uuid,text,uuid,integer) TO "service_role";
DO $absent$ BEGIN IF to_regprocedure('public.fn_pko_claim_predecessor_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_pko_claim_predecessor_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_pko_claim_predecessor_status_v1(p_tournament_id uuid, p_eliminated_user_id uuid, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  target public.tournament_knockout_candidates%ROWTYPE;
  c public.tournament_knockout_candidates%ROWTYPE;
  o public.tournament_bounty_obligations%ROWTYPE;
  target_scope jsonb; prior_scope jsonb; claims jsonb;
  target_commit timestamptz; prior_commit timestamptz;
  inspected integer:=0; checked integer:=0;
  -- Reviewable work bound; never a truncated successful dependency proof.
  scope_limit constant integer:=10000;
  blocked jsonb:='[]'::jsonb; unknown jsonb:='[]'::jsonb;
  detail jsonb; known_marker boolean; conflicting_recipient_narrative boolean;
  same_accepted_hand boolean;
BEGIN
  IF p_tournament_id IS NULL OR p_eliminated_user_id IS NULL
     OR p_table_id IS NULL OR p_hand_id IS NULL OR p_hand_number IS NULL
     OR p_seat_joined_at IS NULL THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','target_identity_required');
  END IF;
  SELECT * INTO target FROM public.tournament_knockout_candidates
   WHERE tournament_id=p_tournament_id AND hand_number=p_hand_number
     AND eliminated_user_id=p_eliminated_user_id;
  IF NOT FOUND OR target.table_id IS DISTINCT FROM p_table_id
     OR target.hand_id IS DISTINCT FROM p_hand_id
     OR target.seat_joined_at IS DISTINCT FROM p_seat_joined_at THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','target_identity_conflict');
  END IF;
  target_scope:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,target.id);
  IF target_scope->>'ok' IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','target_evidence_unproven',
      'detail',target_scope);
  END IF;
  target_commit:=(target_scope->>'committed_at')::timestamptz;

  -- A pending debt without its exact accepted candidate is not invisible work.
  -- Candidate enumeration alone cannot discharge this orphaned payment record.
  IF EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations debt
     WHERE debt.tournament_id=p_tournament_id AND debt.mode='pko' AND debt.state='pending'
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_knockout_candidates candidate
          WHERE candidate.tournament_id=debt.tournament_id
            AND candidate.eliminated_user_id=debt.eliminated_user_id
            AND candidate.hand_number=debt.hand_number AND candidate.table_id=debt.table_id
            AND candidate.hand_id=debt.hand_id AND candidate.seat_joined_at=debt.seat_joined_at)
  ) THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','pending_pko_candidate_missing');
  END IF;

  -- Existing (tournament_id,hand_number,eliminated_user_id) unique index.
  -- The ordering is a scan cursor only, NOT chronological proof. Preallocation
  -- at another table can give an earlier accepted predecessor a larger number.
  FOR c IN SELECT * FROM public.tournament_knockout_candidates
    WHERE tournament_id=p_tournament_id
      AND eliminated_user_id<>p_eliminated_user_id
    ORDER BY hand_number,eliminated_user_id LIMIT scope_limit+1
  LOOP
    inspected:=inspected+1;
    IF inspected>scope_limit THEN
      RETURN jsonb_build_object('ok',false,'status','unknown','reason','predecessor_scope_incomplete',
        'inspected',scope_limit,'scope_limit',scope_limit,'predecessors',blocked,'unknown',unknown);
    END IF;
    -- Same-hand dependence uses the same exact marker proof as cross-hand
    -- dependence. The original side-pot/tie guard remains an additional veto,
    -- but its settled state alone is no longer enough to skip this proof.
    same_accepted_hand:=c.hand_id=p_hand_id AND c.table_id=p_table_id AND c.hand_number=p_hand_number;
    detail:=jsonb_build_object('candidate_id',c.id,'eliminated_user_id',c.eliminated_user_id,
      'table_id',c.table_id,'hand_id',c.hand_id,'hand_number',c.hand_number,
      'seat_joined_at',c.seat_joined_at,'candidate_state',c.state);
    prior_scope:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,c.id);
    IF prior_scope->>'ok' IS DISTINCT FROM 'true' THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','candidate_evidence_unproven','detail',prior_scope));
      END IF;
      CONTINUE;
    END IF;
    -- A complete accepted participant map proves a different table's head
    -- cannot flow into this player. No marker/pot work for that hand.
    IF NOT (prior_scope->'participants' ? p_eliminated_user_id::text) THEN
      -- Malformed history must not name an absent accepted participant as a
      -- recipient/eligible player. A raw scalar mention is only an UNKNOWN
      -- conflict witness, never attribution; JSONPath safely handles scalars.
      SELECT coalesce(jsonb_path_exists(h.pots,'$.** ? (@ == $uid)',
               jsonb_build_object('uid',p_eliminated_user_id::text)),false)
          OR coalesce(jsonb_path_exists(h.winners,'$.** ? (@ == $uid)',
               jsonb_build_object('uid',p_eliminated_user_id::text)),false)
        INTO conflicting_recipient_narrative FROM public.hand_history h
       WHERE h.id=c.hand_id;
      IF conflicting_recipient_narrative IS TRUE THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','recipient_outside_accepted_roster'));
        END IF;
      END IF;
      CONTINUE;
    END IF;
    prior_commit:=(prior_scope->>'committed_at')::timestamptz;
    IF NOT same_accepted_hand AND prior_commit>target_commit THEN CONTINUE; END IF;
    IF NOT same_accepted_hand AND prior_commit=target_commit THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','cross_hand_causal_order_unproven'));
      END IF;
      CONTINUE;
    END IF;
    checked:=checked+1;
    -- Exact lookup by unique key, then compare every immutable identity.
    SELECT * INTO o FROM public.tournament_bounty_obligations
     WHERE tournament_id=p_tournament_id AND hand_number=c.hand_number
       AND eliminated_user_id=c.eliminated_user_id;
    IF FOUND THEN
      IF o.table_id IS DISTINCT FROM c.table_id OR o.hand_id IS DISTINCT FROM c.hand_id
         OR o.seat_joined_at IS DISTINCT FROM c.seat_joined_at OR o.mode IS DISTINCT FROM 'pko'
         OR o.settlement_completed_at IS DISTINCT FROM (prior_scope->>'settlement_completed_at')::timestamptz THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_obligation_identity_conflict','obligation_id',o.id));
        END IF;
        CONTINUE;
      END IF;
      IF jsonb_typeof(o.claimants) IS DISTINCT FROM 'array' THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_claimants_malformed','obligation_id',o.id));
        END IF;
        CONTINUE;
      END IF;
      IF jsonb_array_length(o.claimants)=0 OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(o.claimants) e
         WHERE coalesce(e->>'user_id','') !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR e->>'weight' IS DISTINCT FROM '1'
      ) THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_claimants_malformed','obligation_id',o.id));
        END IF;
        CONTINUE;
      END IF;
      IF jsonb_array_length(o.claimants)<>(SELECT count(DISTINCT (e->>'user_id')::uuid)
            FROM jsonb_array_elements(o.claimants) e)
         OR o.claimants @> jsonb_build_array(jsonb_build_object('user_id',o.eliminated_user_id,'weight',1)) THEN
        IF jsonb_array_length(unknown)<20 THEN
          unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_claimants_malformed','obligation_id',o.id));
        END IF;
        CONTINUE;
      END IF;
    END IF;
    BEGIN
      claims:=public.fn_exact_tournament_knockout_claimants(p_tournament_id,c.hand_id,c.eliminated_user_id);
    EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR numeric_value_out_of_range THEN
      -- Only malformed read evidence is classified here. Cancellation,
      -- connection, permissions, and unexpected execution errors propagate.
      claims:=NULL;
    END;
    IF jsonb_typeof(claims) IS DISTINCT FROM 'array' THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_recipients_unproven'));
      END IF;
      CONTINUE;
    END IF;
    IF jsonb_array_length(claims)=0 THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_recipients_unproven'));
      END IF;
      CONTINUE;
    END IF;
    IF o.id IS NOT NULL AND o.claimants IS DISTINCT FROM claims THEN
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_claimant_snapshot_conflict','obligation_id',o.id));
      END IF;
      CONTINUE;
    END IF;
    IF NOT (claims @> jsonb_build_array(jsonb_build_object('user_id',p_eliminated_user_id,'weight',1))) THEN CONTINUE; END IF;
    IF o.id IS NOT NULL AND o.state='settled' THEN
      -- The marker discharges the accepted predecessor only after its exact
      -- recipient and settlement identities have also matched.
      IF public.fn_bounty_obligation_has_complete_marker(o.id) THEN CONTINUE; END IF;
      IF jsonb_array_length(unknown)<20 THEN
        unknown:=unknown||jsonb_build_array(detail||jsonb_build_object('reason','predecessor_marker_incomplete','obligation_id',o.id));
      END IF;
      CONTINUE;
    END IF;
    IF jsonb_array_length(blocked)<20 THEN
      blocked:=blocked||jsonb_build_array(detail||jsonb_build_object('obligation_id',o.id,
        'committed_at',prior_commit,'claimants',claims,
        'reason',CASE WHEN o.id IS NOT NULL THEN 'pending_pko_predecessor'
          WHEN c.state='pending' THEN 'unclaimed_pko_predecessor'
          ELSE 'closed_predecessor_claim_missing' END,
        'recovery_required',o.id IS NULL AND c.state<>'pending'));
    END IF;
  END LOOP;
  IF jsonb_array_length(unknown)>0 THEN
    RETURN jsonb_build_object('ok',false,'status','unknown','reason','predecessor_evidence_unproven',
      'inspected',inspected,'checked',checked,'predecessors',blocked,'unknown',unknown);
  END IF;
  IF jsonb_array_length(blocked)>0 THEN
    RETURN jsonb_build_object('ok',false,'status','blocked','reason','unsettled_pko_predecessor',
      'inspected',inspected,'checked',checked,'predecessors',blocked);
  END IF;
  RETURN jsonb_build_object('ok',true,'status','clear','inspected',inspected,'checked',checked);
END;
$function$;
ALTER FUNCTION public.fn_pko_claim_predecessor_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_pko_claim_predecessor_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_pko_claim_predecessor_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_pko_watermark_admission_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone,jsonb)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_pko_watermark_admission_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone,jsonb)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_pko_watermark_admission_status_v1(p_tournament_id uuid, p_eliminated_user_id uuid, p_table_id uuid, p_hand_id uuid, p_hand_number bigint, p_seat_joined_at timestamp with time zone, p_claimants jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  participants uuid[]; others uuid[]; target_candidate uuid;
  target_scope jsonb; later_scope jsonb; exact_claimants jsonb;
  target_commit timestamptz; later_commit timestamptz;
  watermark bigint; watermark_obligation uuid;
  o public.tournament_bounty_obligations%ROWTYPE;
  c public.tournament_knockout_candidates%ROWTYPE;
  inspected integer:=0; scope_limit constant integer:=10000;
  overlapping boolean;
BEGIN
  IF p_tournament_id IS NULL OR p_eliminated_user_id IS NULL OR p_table_id IS NULL
     OR p_hand_id IS NULL OR p_hand_number IS NULL OR p_seat_joined_at IS NULL
     OR jsonb_typeof(p_claimants) IS DISTINCT FROM 'array' THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_identity_unproven');
  END IF;
  IF jsonb_array_length(p_claimants)=0 OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(p_claimants) e
     WHERE coalesce(e->>'user_id','') !~*
       '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR e->>'weight' IS DISTINCT FROM '1'
  ) THEN RETURN jsonb_build_object('ok',false,'reason','watermark_target_claimants_unproven'); END IF;
  SELECT ARRAY[p_eliminated_user_id]||array_agg((e->>'user_id')::uuid)
    INTO participants FROM jsonb_array_elements(p_claimants) e;
  IF cardinality(participants)<>(SELECT count(DISTINCT u) FROM unnest(participants) u)
     OR EXISTS (SELECT 1 FROM unnest(participants[2:cardinality(participants)]) u
         WHERE NOT EXISTS (SELECT 1 FROM public.tournament_players tp
          WHERE tp.tournament_id=p_tournament_id AND tp.user_id=u AND tp.status='playing')) THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_generation_unproven');
  END IF;
  SELECT id INTO target_candidate FROM public.tournament_knockout_candidates
   WHERE tournament_id=p_tournament_id AND hand_number=p_hand_number
     AND eliminated_user_id=p_eliminated_user_id AND table_id=p_table_id
     AND hand_id=p_hand_id AND seat_joined_at=p_seat_joined_at;
  IF target_candidate IS NULL THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_candidate_missing');
  END IF;
  target_scope:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,target_candidate);
  IF target_scope->>'ok' IS DISTINCT FROM 'true' THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_evidence_unproven','detail',target_scope);
  END IF;
  BEGIN
    exact_claimants:=public.fn_exact_tournament_knockout_claimants(p_tournament_id,p_hand_id,p_eliminated_user_id);
  EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR numeric_value_out_of_range THEN
    exact_claimants:=NULL;
  END;
  IF exact_claimants IS DISTINCT FROM p_claimants THEN
    RETURN jsonb_build_object('ok',false,'reason','watermark_target_claimants_conflict');
  END IF;
  target_commit:=(target_scope->>'committed_at')::timestamptz;
  SELECT w.last_settled_hand_number,w.last_obligation_id
    INTO watermark,watermark_obligation FROM public.tournament_pko_settlement_watermarks w
    JOIN public.tournament_bounty_obligations b ON b.id=w.last_obligation_id
     AND b.tournament_id=w.tournament_id AND b.hand_number=w.last_settled_hand_number
     AND b.state='settled' AND b.mode='pko'
   WHERE w.tournament_id=p_tournament_id;
  -- This helper is only the exception for a caller which saw a greater
  -- watermark. Missing/corrupt/not-applicable state cannot authorize it.
  IF watermark IS NULL OR watermark<=p_hand_number OR EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations b
     WHERE b.tournament_id=p_tournament_id AND b.mode='pko'
       AND b.state='settled' AND b.hand_number>watermark
  ) THEN RETURN jsonb_build_object('ok',false,'reason','watermark_identity_unproven'); END IF;

  FOR o IN SELECT * FROM public.tournament_bounty_obligations
    WHERE tournament_id=p_tournament_id AND mode='pko' AND hand_number>p_hand_number
    ORDER BY hand_number,eliminated_user_id LIMIT scope_limit+1
  LOOP
    inspected:=inspected+1;
    IF inspected>scope_limit THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_scope_incomplete','inspected',scope_limit);
    END IF;
    IF jsonb_typeof(o.claimants) IS DISTINCT FROM 'array' THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_claimants_unproven','obligation_id',o.id);
    END IF;
    IF jsonb_array_length(o.claimants)=0 OR EXISTS (
      SELECT 1 FROM jsonb_array_elements(o.claimants) e
       WHERE coalesce(e->>'user_id','') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR e->>'weight' IS DISTINCT FROM '1'
    ) THEN RETURN jsonb_build_object('ok',false,'reason','watermark_claimants_unproven','obligation_id',o.id); END IF;
    SELECT ARRAY[o.eliminated_user_id]||array_agg((e->>'user_id')::uuid)
      INTO others FROM jsonb_array_elements(o.claimants) e;
    IF cardinality(others)<>(SELECT count(DISTINCT u) FROM unnest(others) u)
       OR o.state IS NULL OR o.state NOT IN ('pending','settled') OR o.table_id IS NULL THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_obligation_unproven','obligation_id',o.id);
    END IF;
    IF o.state='settled' AND public.fn_bounty_obligation_has_complete_marker(o.id) IS NOT TRUE THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_marker_incomplete','obligation_id',o.id);
    END IF;
    overlapping:=o.table_id=p_table_id OR others && participants;
    -- Preserve R35's disjoint-table commutativity, including complete later
    -- settled heads and disjoint pending snapshots. Extra chronology is only
    -- needed to admit a SHARED participant/table after a larger hand number.
    IF NOT overlapping THEN CONTINUE; END IF;
    IF o.state IS DISTINCT FROM 'settled' THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_shared_head_pending','obligation_id',o.id);
    END IF;
    SELECT * INTO c FROM public.tournament_knockout_candidates
     WHERE tournament_id=p_tournament_id AND hand_number=o.hand_number
       AND eliminated_user_id=o.eliminated_user_id;
    IF NOT FOUND OR c.table_id IS DISTINCT FROM o.table_id
       OR c.hand_id IS DISTINCT FROM o.hand_id OR c.seat_joined_at IS DISTINCT FROM o.seat_joined_at THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_prior_candidate_conflict','obligation_id',o.id);
    END IF;
    later_scope:=public.fn_pko_candidate_accepted_scope_v1(p_tournament_id,c.id);
    IF later_scope->>'ok' IS DISTINCT FROM 'true' THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_prior_evidence_unproven',
        'obligation_id',o.id,'detail',later_scope);
    END IF;
    IF (later_scope->>'settlement_completed_at')::timestamptz IS DISTINCT FROM o.settlement_completed_at THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_prior_settlement_conflict','obligation_id',o.id);
    END IF;
    BEGIN
      exact_claimants:=public.fn_exact_tournament_knockout_claimants(p_tournament_id,c.hand_id,c.eliminated_user_id);
    EXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR numeric_value_out_of_range THEN
      exact_claimants:=NULL;
    END;
    IF exact_claimants IS DISTINCT FROM o.claimants THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_prior_claimants_conflict','obligation_id',o.id);
    END IF;
    later_commit:=(later_scope->>'committed_at')::timestamptz;
    IF later_commit>=target_commit THEN
      RETURN jsonb_build_object('ok',false,'reason','watermark_shared_head_not_causally_prior',
        'obligation_id',o.id,'prior_committed_at',later_commit,'target_committed_at',target_commit);
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok',true,'reason','independent_or_causally_prior',
    'inspected',inspected,'watermark',watermark);
END;
$function$;
ALTER FUNCTION public.fn_pko_watermark_admission_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone,jsonb) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_pko_watermark_admission_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone,jsonb) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_pko_watermark_admission_status_v1(uuid,uuid,uuid,uuid,bigint,timestamp with time zone,jsonb) TO "postgres";
DO $absent$ BEGIN IF to_regprocedure('public.fn_sweep_pending_tournament_bounties(uuid,integer)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_sweep_pending_tournament_bounties(uuid,integer)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_sweep_pending_tournament_bounties(p_tournament_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  candidate record;
  v_result jsonb;
  v_reserved jsonb;
  v_award_id uuid;
  v_processed integer := 0;
  v_settled integer := 0;
  v_failed integer := 0;
  v_settled_tournament_ids uuid[] := ARRAY[]::uuid[];
  v_recipients jsonb;
  v_op_hex text;
  v_op_id uuid;
  v_limit integer := GREATEST(1,LEAST(COALESCE(p_limit,20),100));
  v_scope uuid := p_tournament_id;
BEGIN
  -- ONE TOURNAMENT'S LANE PER CALL (2026-09-10). Called without a tournament
  -- (the engine does that on every pending-obligation notification, i.e. on
  -- every bounty bust) this used to take the WHOLE lane - G and B exclusive -
  -- which held every hand settlement and every rolling authority on the
  -- platform for the length of the sweep. It now settles the tournament of
  -- the first order-eligible due obligation under that tournament's lane (G
  -- shared, T(id) exclusive) and nothing else. 'pending' and 'retry_after_ms'
  -- below still describe the whole platform, so the engine calls again at
  -- once while other tournaments have due work. One tournament per call also
  -- means a transaction never holds two tournaments' lanes.
  IF v_scope IS NULL THEN
    SELECT bo.tournament_id INTO v_scope
      FROM public.tournament_bounty_obligations bo
     WHERE bo.state = 'pending'
       AND bo.next_attempt_at <= now()
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_obligations prior
          WHERE prior.tournament_id=bo.tournament_id AND prior.state='pending'
            AND prior.mode='pko'
            AND (prior.hand_number < bo.hand_number
                 OR (prior.hand_number=bo.hand_number
                     AND prior.eliminated_user_id::text < bo.eliminated_user_id::text))
       )
     ORDER BY bo.next_attempt_at, bo.tournament_id, bo.hand_number,
              bo.eliminated_user_id
     LIMIT 1;
  END IF;
  IF v_scope IS NOT NULL THEN
    PERFORM public.fn_ca_lock_settlement_lane_for_tournament(v_scope);
  END IF;
  FOR candidate IN
    SELECT bo.id, bo.tournament_id FROM public.tournament_bounty_obligations bo
     WHERE bo.state = 'pending'
       AND bo.next_attempt_at <= now()
       AND bo.tournament_id = v_scope
       AND NOT EXISTS (
         SELECT 1 FROM public.tournament_bounty_obligations prior
          WHERE prior.tournament_id=bo.tournament_id AND prior.state='pending'
            AND prior.mode='pko'
            AND (prior.hand_number < bo.hand_number
                 OR (prior.hand_number=bo.hand_number
                     AND prior.eliminated_user_id::text < bo.eliminated_user_id::text))
       )
     ORDER BY bo.next_attempt_at, bo.tournament_id, bo.hand_number,
              bo.eliminated_user_id
     LIMIT v_limit
  LOOP
    BEGIN
      -- One lock order everywhere: tournament then obligation. Direct manager
      -- collection also locks tournament before its ledger trigger touches the
      -- outbox, so the global lane cannot deadlock it outbox->tournament.
      PERFORM 1 FROM public.tournaments t WHERE t.id=candidate.tournament_id FOR UPDATE;
      SELECT * INTO o FROM public.tournament_bounty_obligations bo
       WHERE bo.id=candidate.id AND bo.state='pending' AND bo.next_attempt_at<=now()
       FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN CONTINUE; END IF;
      -- The candidate query ran before these locks. Re-prove ordering after the
      -- tournament and exact obligation are locked so a predecessor committed
      -- in that window cannot be skipped.
      IF o.mode='pko' AND EXISTS (
        SELECT 1 FROM public.tournament_bounty_obligations prior
         WHERE prior.tournament_id=o.tournament_id AND prior.mode='pko'
           AND prior.state='pending'
           AND (prior.hand_number<o.hand_number
                OR (prior.hand_number=o.hand_number
                    AND prior.eliminated_user_id::text<o.eliminated_user_id::text))
      ) THEN
        CONTINUE;
      END IF;
      v_processed := v_processed + 1;

      -- Response-loss reconciliation before another call.
      IF o.mode <> 'mystery_chest'
         AND public.fn_bounty_obligation_has_complete_marker(o.id) THEN
        UPDATE public.tournament_bounty_obligations SET state='settled', settled_at=now(), last_error=NULL
         WHERE id=o.id;
        v_settled := v_settled + 1;
        IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
          v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
        END IF;
        CONTINUE;
      ELSIF o.mode = 'mystery_chest'
         AND public.fn_bounty_obligation_has_complete_marker(o.id) THEN
        UPDATE public.tournament_bounty_obligations SET state='settled', settled_at=now(), last_error=NULL
         WHERE id=o.id;
        v_settled := v_settled + 1;
        IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
          v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
        END IF;
        CONTINUE;
      END IF;

      IF o.mode = 'mystery_chest' THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
          'user_id', x.user_id, 'weight', x.weight,
          'is_designated_revealer', x.user_id = o.knocker_user_id
        )), '[]'::jsonb)
        INTO v_recipients
        FROM (
          SELECT (e->>'user_id')::uuid AS user_id,
                 GREATEST(COALESCE((e->>'weight')::numeric, 0), 0) AS weight
            FROM jsonb_array_elements(o.claimants) e
           WHERE NULLIF(e->>'user_id','') IS NOT NULL
        ) x;
        v_op_hex := md5('mb:' || o.id::text);
        v_op_id := (substr(v_op_hex,1,8)||'-'||substr(v_op_hex,9,4)||'-4'||substr(v_op_hex,14,3)
          ||'-8'||substr(v_op_hex,18,3)||'-'||substr(v_op_hex,21,12))::uuid;
        v_reserved := public.fn_mystery_bounty_reserve(
          o.tournament_id, o.eliminated_user_id, v_recipients, o.table_id,
          o.hand_id::text, v_op_id, 1);
        IF NOT COALESCE((v_reserved->>'ok')::boolean, false) THEN
          RAISE EXCEPTION 'reserve refused: %', COALESCE(v_reserved->>'reason','unknown');
        END IF;
        v_award_id := (v_reserved->>'award_id')::uuid;
        IF COALESCE(v_reserved->>'status','') <> 'completed' THEN
          v_result := public.fn_mystery_bounty_reveal(v_award_id, NULL, true);
          IF NOT COALESCE((v_result->>'ok')::boolean, false) THEN
            RAISE EXCEPTION 'reveal refused';
          END IF;
          v_result := public.fn_mystery_bounty_pay(v_award_id);
          IF NOT COALESCE((v_result->>'ok')::boolean, false)
             OR COALESCE((v_result->>'refused_recipients')::integer,0) > 0 THEN
            RAISE EXCEPTION 'pay refused or incomplete';
          END IF;
        END IF;
        IF NOT EXISTS (SELECT 1 FROM public.tournament_bounty_awards a
                        WHERE a.bounty_obligation_id=o.id AND a.status='completed') THEN
          RAISE EXCEPTION 'mystery payout has no completed award marker';
        END IF;
      ELSE
        v_result := public.fn_collect_bounty_obligation(o.id);
        IF NOT COALESCE((v_result->>'ok')::boolean, false)
           AND COALESCE(v_result->>'reason','') <> 'already_collected' THEN
          RAISE EXCEPTION 'collect refused: %', COALESCE(v_result->>'reason','unknown');
        END IF;
        IF NOT public.fn_bounty_obligation_has_complete_marker(o.id) THEN
          RAISE EXCEPTION 'fixed/PKO payout markers do not conserve the full generation head';
        END IF;
      END IF;

      -- Triggers settle only after every canonical claimant (or the completed
      -- award) is durable. Never infer success from an RPC transport response.
      IF NOT EXISTS (SELECT 1 FROM public.tournament_bounty_obligations x
                      WHERE x.id=o.id AND x.state='settled') THEN
        RAISE EXCEPTION 'payout marker did not acknowledge obligation';
      END IF;
      UPDATE public.tournament_bounty_obligations
         SET last_error=NULL, attempt_count=attempt_count+1
       WHERE id=o.id;
      v_settled := v_settled + 1;
      IF NOT o.tournament_id=ANY(v_settled_tournament_ids) THEN
        v_settled_tournament_ids := array_append(v_settled_tournament_ids,o.tournament_id);
      END IF;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.tournament_bounty_obligations
       SET attempt_count=attempt_count+1, last_error=left(SQLERRM,1000),
             next_attempt_at=clock_timestamp()
               + make_interval(secs => LEAST(60, 5 * (attempt_count + 1)))
       WHERE id=candidate.id;
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'processed', v_processed,
    'settled', v_settled, 'failed', v_failed,
    'settled_tournament_ids',to_jsonb(v_settled_tournament_ids),
    'pending', (SELECT count(*) FROM public.tournament_bounty_obligations
      WHERE state='pending' AND (p_tournament_id IS NULL OR tournament_id=p_tournament_id)),
    -- Return a DATABASE-CLOCK RELATIVE delay for the first order-eligible
    -- head. A later PKO row can have due=now while an earlier generation is
    -- backed off; using the raw minimum would spin the engine until the head
    -- became due. A host timestamp would repeat that bug under clock skew.
    'retry_after_ms',(
      SELECT CASE WHEN due_at IS NULL THEN NULL ELSE
        GREATEST(0,ceil(extract(epoch FROM (due_at-clock_timestamp()))*1000)::bigint)
      END
      FROM (
        SELECT min(bo.next_attempt_at) AS due_at
          FROM public.tournament_bounty_obligations bo
         WHERE bo.state='pending'
           AND (p_tournament_id IS NULL OR bo.tournament_id=p_tournament_id)
           AND NOT EXISTS (
             SELECT 1 FROM public.tournament_bounty_obligations prior
              WHERE prior.tournament_id=bo.tournament_id AND prior.state='pending'
                AND prior.mode='pko'
                AND (prior.hand_number<bo.hand_number
                     OR (prior.hand_number=bo.hand_number
                         AND prior.eliminated_user_id::text<bo.eliminated_user_id::text))
           )
      ) eligible_head
    ));
END;
$function$;
ALTER FUNCTION public.fn_sweep_pending_tournament_bounties(uuid,integer) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_sweep_pending_tournament_bounties(uuid,integer) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_sweep_pending_tournament_bounties(uuid,integer) TO "postgres";
GRANT EXECUTE ON FUNCTION public.fn_sweep_pending_tournament_bounties(uuid,integer) TO "service_role";
DO $absent$ BEGIN IF to_regprocedure('public.process_tournament_rebuy(uuid,uuid,text,numeric,numeric,integer,text)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.process_tournament_rebuy(uuid,uuid,text,numeric,numeric,integer,text)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.process_tournament_rebuy(p_tournament_id uuid, p_user_id uuid, p_rebuy_type text, p_cost numeric, p_chips numeric, p_current_level integer DEFAULT NULL::integer, p_client_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_type text:=lower(btrim(COALESCE(p_rebuy_type,'')));
  v_effective_token text;
  v_receipt_key text;
  v_request jsonb;
  v_existing_request jsonb;
  v_existing_response jsonb;
  v_claim jsonb;
  v_response jsonb;
  v_recorded jsonb;
  v_gate jsonb;
  v_choice jsonb;
  v_assignment jsonb;
  v_t public.tournaments%ROWTYPE;
  v_player public.tournament_players%ROWTYPE;
  v_candidate_peek public.tournament_knockout_candidates%ROWTYPE;
  v_candidate public.tournament_knockout_candidates%ROWTYPE;
  v_live public.table_seats%ROWTYPE;
  v_final_seat public.table_seats%ROWTYPE;
  v_table_id uuid;
  v_seat_number integer;
  v_live_count integer;
  v_pending_count integer;
  v_rebuy_window jsonb;
  v_bounty_settlement jsonb;
  v_bounty_obligation_id uuid;
  v_rows integer;
  v_wake_id bigint;
  v_expected_club_id uuid;
  v_expected_horse_id uuid;
  v_previous_money_path text:=current_setting('app.money_path',true);
BEGIN
  IF NOT public.fn_caller_session_is_live() THEN
    RAISE EXCEPTION
      'SESSION_REVOKED: this session is signed out - sign in again'
      USING ERRCODE='28000';
  END IF;
  IF p_tournament_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'tournament and player are required'
      USING ERRCODE='22023';
  END IF;
  IF v_type NOT IN ('rebuy','reentry','addon') THEN
    RAISE EXCEPTION 'Invalid rebuy type: %',p_rebuy_type
      USING ERRCODE='22023';
  END IF;
  IF COALESCE(auth.role(),'service_role')<>'service_role'
     AND (auth.uid() IS NULL OR auth.uid()<>p_user_id) THEN
    RAISE EXCEPTION
      'process_tournament_rebuy: caller may only transact for themselves'
      USING ERRCODE='42501';
  END IF;
  IF p_client_token IS NOT NULL
     AND (length(btrim(p_client_token))=0
          OR length(btrim(p_client_token))>128) THEN
    RAISE EXCEPTION 'rebuy prompt token is invalid'
      USING ERRCODE='22023';
  END IF;
  IF v_type<>'addon'
     AND COALESCE(auth.role(),'service_role')<>'service_role'
     AND p_client_token IS NULL THEN
    RAISE EXCEPTION 'a rebuy prompt token is required'
      USING ERRCODE='22023';
  END IF;

  -- Every chip purchase can change the tournament pool, even an add-on that
  -- does not acquire a new chair. Join terminal settlement and maintenance at
  -- their common root before claiming a receipt; an already-committed receipt
  -- can still replay after either boundary without rerunning money.
  PERFORM public.fn_ca_lock_settlement_lane_for_tournament(p_tournament_id);
  PERFORM pg_advisory_xact_lock_shared(530090,1);

  IF v_type='addon' THEN
    -- Add-ons never create a chair, but their committed receipt must remain
    -- replayable across the maintenance boundary.
    v_receipt_key:='tourney:'||p_tournament_id::text||':addon:'||
      p_user_id::text;
    v_request:=jsonb_build_object(
      'version','v1','tournament_id',p_tournament_id,'user_id',p_user_id,
      'rebuy_type',v_type,'idempotency_key',v_receipt_key);
  ELSIF p_client_token IS NOT NULL
        AND length(btrim(p_client_token))>0 THEN
    v_effective_token:=btrim(p_client_token);
    v_receipt_key:='tourney:'||p_tournament_id::text||':'||v_type||':'||
      p_user_id::text||':tok:'||v_effective_token;
  END IF;

  -- An explicit prompt token names its historical purchase independently of
  -- whichever hand is current now. Read that immutable receipt first, so a
  -- delayed transport retry after later play returns the original answer
  -- instead of trying to bind the token to a newer knockout generation.
  IF v_receipt_key IS NOT NULL THEN
    SELECT r.request,r.response
      INTO v_existing_request,v_existing_response
      FROM public.entry_purchase_idempotency_receipts r
     WHERE r.key_domain='tournament_chip_purchase'
       AND r.idempotency_key=v_receipt_key;
    IF FOUND THEN
      IF v_existing_response IS NULL
         OR v_existing_request->>'version'<>'v1'
         OR v_existing_request->>'tournament_id'<>p_tournament_id::text
         OR v_existing_request->>'user_id'<>p_user_id::text
         OR v_existing_request->>'rebuy_type'<>v_type
         OR v_existing_request->>'idempotency_key'<>v_receipt_key
         OR v_existing_response->>'success'<>'true'
         OR v_existing_response->>'seated'<>'true'
         OR v_existing_response->>'atomic_tournament_chip_purchase'<>'v1'
         OR v_existing_response->>'rebuy_type'<>v_type
         OR v_existing_response->>'table_id' IS NULL
         OR v_existing_response->>'seat_id' IS NULL
         OR v_existing_response->>'stack' IS NULL
         OR (v_type='addon' AND v_existing_request ? 'candidate_id')
         OR (v_type<>'addon' AND (
           v_existing_request->>'candidate_id' IS NULL
           OR v_existing_response->>'candidate_id'<>
              v_existing_request->>'candidate_id'
           OR v_existing_response->>'candidate_state'<>'rebought')) THEN
        RAISE EXCEPTION
          'IDEMPOTENCY_RECEIPT_UNBOUND: historical response is not an atomic tournament purchase proof'
          USING ERRCODE='55000';
      END IF;
      RETURN v_existing_response;
    END IF;
  END IF;

  IF v_type<>'addon' THEN
    -- A rebuy can acquire/revive a chair, so it joins the same global root as
    -- every registration, move and terminal settlement before observing a
    -- candidate. The nonlocking peek derives only an immutable identity; the
    -- exact latest row is re-read under tournament/candidate locks below.
    SELECT * INTO v_candidate_peek
      FROM public.tournament_knockout_candidates c
     WHERE c.id=public.fn_ca_latest_committed_knockout_candidate(
       p_tournament_id,p_user_id);
    IF v_candidate_peek.id IS NULL THEN
      RAISE EXCEPTION
        'REBUY_KNOCKOUT_GENERATION_REQUIRED: no immutable bust authorizes this purchase'
        USING ERRCODE='55000';
    END IF;
    IF v_effective_token IS NULL THEN
      v_effective_token:='candidate:'||v_candidate_peek.id::text;
      v_receipt_key:='tourney:'||p_tournament_id::text||':'||v_type||':'||
        p_user_id::text||':tok:'||v_effective_token;
    END IF;
    v_request:=jsonb_build_object(
      'version','v1','tournament_id',p_tournament_id,'user_id',p_user_id,
      'rebuy_type',v_type,'candidate_id',v_candidate_peek.id,
      'idempotency_key',v_receipt_key);
  END IF;

  v_claim:=public.fn_claim_entry_purchase_receipt(
    'tournament_chip_purchase',v_receipt_key,v_request);
  IF COALESCE((v_claim->>'claimed')::boolean,false) IS NOT TRUE THEN
    v_response:=v_claim->'response';
    IF v_response IS NULL
       OR v_response->>'atomic_tournament_chip_purchase'<>'v1'
       OR v_response->>'success'<>'true'
       OR v_response->>'seated'<>'true'
       OR v_response->>'rebuy_type'<>v_type
       OR v_response->>'table_id' IS NULL
       OR v_response->>'seat_id' IS NULL
       OR v_response->>'stack' IS NULL
       OR (v_type<>'addon' AND
           (v_response->>'candidate_id'<>v_candidate_peek.id::text
            OR v_response->>'candidate_state'<>'rebought')) THEN
      RAISE EXCEPTION
        'IDEMPOTENCY_RECEIPT_UNBOUND: historical response is not an atomic tournament purchase proof'
        USING ERRCODE='55000';
    END IF;
    RETURN v_response;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.wallet_credit_idempotency k
     WHERE k.key=v_receipt_key) THEN
    RAISE EXCEPTION
      'IDEMPOTENCY_RECEIPT_UNBOUND: chip key predates its exact transaction receipt'
      USING ERRCODE='55000';
  END IF;

  IF v_type='addon' THEN
    IF public.fn_entry_purchases_frozen() THEN
      RAISE EXCEPTION
        'PLATFORM_FROZEN: scheduled maintenance has closed add-ons; no chips moved'
        USING ERRCODE='55006';
    END IF;
    SELECT s.table_id INTO v_table_id
      FROM public.table_seats s
      JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id
       AND s.user_id=p_user_id AND s.left_at IS NULL
     ORDER BY s.id
     LIMIT 1;
    IF v_table_id IS NULL THEN
      RAISE EXCEPTION 'Add-on requires one live tournament table'
        USING ERRCODE='55000';
    END IF;
    -- The accepted-hand boundary owns this same table key. During a rolling
    -- database cutover it prevents the old hand body from settling over a paid
    -- grant; after 14534, the hand also takes the terminal root shared before
    -- this key, preserving root -> table -> rows on both paths.
    PERFORM pg_advisory_xact_lock(
      hashtextextended('atomic-table:'||v_table_id::text,0));
    SELECT * INTO v_t FROM public.tournaments t
     WHERE t.id=p_tournament_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Tournament not found'; END IF;
    IF COALESCE(v_t.prize_pool_finalized,false)
       OR upper(COALESCE(v_t.status::text,'')) NOT IN ('REGISTERING','RUNNING')
       OR NOT COALESCE(v_t.add_on_available,false)
       OR NOT COALESCE(v_t.addon_period_triggered,false)
       OR v_t.addon_period_started_at IS NULL
       OR v_t.addon_period_ends_at IS NULL
       OR clock_timestamp()<v_t.addon_period_started_at
       OR clock_timestamp()>=v_t.addon_period_ends_at THEN
      RAISE EXCEPTION 'Add-On Period Is Closed Or The Prize Pool Is Already Finalized'
        USING ERRCODE='55000';
    END IF;
    SELECT * INTO v_player FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     FOR UPDATE;
    IF NOT FOUND OR v_player.status::text<>'playing'
       OR COALESCE(v_player.chips,0)<=0 OR COALESCE(v_player.add_on,false) THEN
      RAISE EXCEPTION 'Only one live positive tournament entry may take an add-on'
        USING ERRCODE='55000';
    END IF;
    PERFORM s.id
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL
     ORDER BY s.id FOR UPDATE OF s;
    SELECT count(*)::integer INTO v_live_count
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL;
    IF v_live_count<>1 THEN
      RAISE EXCEPTION 'Add-on requires exactly one locked live tournament seat'
        USING ERRCODE='55000';
    END IF;
    SELECT s.* INTO v_live
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL FOR UPDATE OF s;
    IF v_live.table_id IS DISTINCT FROM v_table_id THEN
      RAISE EXCEPTION 'Add-on live table changed after its atomic-table lock'
        USING ERRCODE='40001';
    END IF;

    v_response:=public.fn_ca_process_tournament_chip_purchase_money_v1(
      p_tournament_id,p_user_id,v_type,p_cost,p_chips,v_t.current_level,
      v_receipt_key);
    IF COALESCE((v_response->>'success')::boolean,false) IS NOT TRUE
       OR COALESCE((v_response->>'idempotent')::boolean,false) THEN
      RAISE EXCEPTION 'tournament add-on money core did not commit a new purchase'
        USING ERRCODE='P0404';
    END IF;
    SELECT * INTO v_player FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;
    SELECT s.* INTO v_final_seat FROM public.table_seats s
     WHERE s.id=v_live.id;
    IF v_player.status::text<>'playing' OR NOT COALESCE(v_player.add_on,false)
       OR v_final_seat.left_at IS NOT NULL
       OR v_final_seat.user_id IS DISTINCT FROM p_user_id
       OR v_final_seat.stack IS DISTINCT FROM v_player.chips::numeric
       OR v_final_seat.stack<=0 OR v_final_seat.stack<>trunc(v_final_seat.stack) THEN
      RAISE EXCEPTION 'atomic add-on seat/roster proof is not exact'
        USING ERRCODE='P0404';
    END IF;
    v_wake_id:=public.fn_emit_tournament_manager_wake(p_tournament_id,'addon');
    v_response:=v_response||jsonb_build_object(
      'success',true,'seated',true,'atomic_tournament_chip_purchase','v1',
      'rebuy_type',v_type,'seat_id',v_final_seat.id,
      'table_id',v_final_seat.table_id,
      'seat_number',v_final_seat.seat_number,'stack',v_final_seat.stack,
      'manager_wake_id',v_wake_id);
  ELSE
    v_table_id:=v_candidate_peek.table_id;
    PERFORM pg_advisory_xact_lock(
      hashtextextended('atomic-table:'||v_table_id::text,0));
    v_gate:=public.fn_ca_lock_tournament_seat_acquisition(
      p_tournament_id,NULL,p_user_id);
    IF COALESCE((v_gate->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'tournament rebuy root refused: %',
        COALESCE(v_gate->>'reason','unknown') USING ERRCODE='55000';
    END IF;
    SELECT * INTO v_t FROM public.tournaments t
     WHERE t.id=p_tournament_id;
    IF COALESCE(v_t.prize_pool_finalized,false)
       OR upper(COALESCE(v_t.status::text,''))<>'RUNNING' THEN
      RAISE EXCEPTION 'Tournament is not accepting rebuys or re-entries'
        USING ERRCODE='55000';
    END IF;
    v_rebuy_window:=public.fn_ca_tournament_rebuy_window(p_tournament_id);
    IF COALESCE((v_rebuy_window->>'open')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'Rebuy period is closed: %',
        COALESCE(v_rebuy_window->>'reason','unknown') USING ERRCODE='55000';
    END IF;

    SELECT * INTO v_player FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id
     FOR UPDATE;
    IF NOT FOUND OR v_player.status::text NOT IN ('playing','eliminated')
       OR COALESCE(v_player.chips,0)>0 OR COALESCE(v_player.prize,0)>0 THEN
      RAISE EXCEPTION 'Only the exact unpaid zero-stack entry may rebuy'
        USING ERRCODE='55000';
    END IF;

    PERFORM c.id FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_user_id
     ORDER BY c.hand_number,c.id FOR UPDATE;
    SELECT count(*) FILTER (WHERE c.state='pending')::integer
      INTO v_pending_count
      FROM public.tournament_knockout_candidates c
     WHERE c.tournament_id=p_tournament_id
       AND c.eliminated_user_id=p_user_id;
    SELECT * INTO v_candidate
      FROM public.tournament_knockout_candidates c
     WHERE c.id=public.fn_ca_latest_committed_knockout_candidate(
       p_tournament_id,p_user_id);
    IF v_candidate.id IS DISTINCT FROM v_candidate_peek.id
       OR v_candidate.state NOT IN ('pending','eliminated')
       OR (v_type='rebuy' AND v_candidate.state<>'pending')
       OR (v_candidate.state='pending' AND
           (v_pending_count<>1 OR v_player.status::text<>'playing'))
       OR (v_candidate.state='eliminated' AND
           (v_pending_count<>0 OR v_player.status::text<>'eliminated'))
       OR EXISTS (
         SELECT 1 FROM public.tournament_knockout_candidates prior
          WHERE prior.tournament_id=p_tournament_id
            AND prior.eliminated_user_id=p_user_id
            AND (prior.hand_number,prior.id)<
                (v_candidate.hand_number,v_candidate.id)
            AND prior.state<>'rebought') THEN
      RAISE EXCEPTION 'UNRESOLVED_KNOCKOUT_GENERATION_CHAIN'
        USING ERRCODE='P0404';
    END IF;
    IF v_candidate.state='pending'
       AND (v_candidate.rebuy_prompt_until IS NULL
            OR v_candidate.rebuy_prompt_until<=clock_timestamp()) THEN
      RAISE EXCEPTION 'Rebuy or re-entry decision window has closed'
        USING ERRCODE='55000';
    END IF;
    IF COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
       OR COALESCE(v_t.is_mystery_bounty,false) THEN
      v_bounty_settlement:=
        public.fn_ca_settle_bounty_rebuy_generation_v1(
          p_tournament_id,p_user_id,v_candidate.id);
      BEGIN
        v_bounty_obligation_id:=
          (v_bounty_settlement->>'obligation_id')::uuid;
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'Bounty settlement returned no exact generation id'
          USING ERRCODE='P0404';
      END;
      IF COALESCE((v_bounty_settlement->>'ok')::boolean,false) IS NOT TRUE
         OR COALESCE(v_bounty_settlement->>'marker_verified','false')<>'true'
         OR COALESCE(v_bounty_settlement->>'old_head_cleared','false')<>'true'
         OR NOT EXISTS (
           SELECT 1 FROM public.tournament_bounty_obligations o
            WHERE o.id=v_bounty_obligation_id
              AND o.tournament_id=p_tournament_id
              AND o.eliminated_user_id=p_user_id
              AND o.hand_number=v_candidate.hand_number
              AND o.hand_id=v_candidate.hand_id
              AND o.state='settled'
              AND public.fn_bounty_obligation_has_complete_marker(o.id)) THEN
        RAISE EXCEPTION
          'Bounty Settlement Pending - Rebuy Or Re-Entry Cannot Replace This Entry Generation Yet'
          USING ERRCODE='55000';
      END IF;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.tournament_obligations o
       WHERE o.tournament_id=p_tournament_id AND o.user_id=p_user_id
         AND o.kind='bubble_protection' AND o.amount_paid=o.amount_owed
         AND o.amount_paid>0 AND o.settled_at IS NOT NULL) THEN
      RAISE EXCEPTION
        'Bubble Protection Already Paid - This Result Cannot Be Resurrected'
        USING ERRCODE='55000';
    END IF;

    PERFORM s.id
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL
     ORDER BY s.id FOR UPDATE OF s;
    SELECT count(*)::integer INTO v_live_count
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL;
    IF v_live_count>1 THEN
      RAISE EXCEPTION 'tournament rebuy found multiple live seats'
        USING ERRCODE='P0404';
    ELSIF v_live_count=1 THEN
      SELECT s.* INTO v_live
        FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
       WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
         AND s.left_at IS NULL FOR UPDATE OF s;
      IF v_live.id IS DISTINCT FROM v_candidate.seat_id
         OR v_live.table_id IS DISTINCT FROM v_candidate.table_id
         OR v_live.joined_at IS DISTINCT FROM v_candidate.seat_joined_at
         OR COALESCE(v_live.stack,0)<>0 THEN
        RAISE EXCEPTION 'knockout generation has a different live seat'
          USING ERRCODE='P0404';
      END IF;
      v_table_id:=v_live.table_id;
      v_seat_number:=v_live.seat_number;
    END IF;

    v_response:=public.fn_ca_process_tournament_chip_purchase_money_v1(
      p_tournament_id,p_user_id,v_type,p_cost,p_chips,v_t.current_level,
      v_effective_token);
    IF COALESCE((v_response->>'success')::boolean,false) IS NOT TRUE
       OR COALESCE((v_response->>'idempotent')::boolean,false) THEN
      RAISE EXCEPTION 'tournament rebuy money core did not commit a new purchase'
        USING ERRCODE='P0404';
    END IF;

    -- A seatless eliminated entry is not counted as active capacity until the
    -- money core promotes it. Choose the chair only after that in-transaction
    -- promotion; any capacity/assignment failure below aborts the debit and
    -- every pool leg with it, so a purchase can never commit seatless.
    IF v_live_count=0 THEN
      v_choice:=public.fn_ca_choose_tournament_seat_locked(
        p_tournament_id,p_user_id,v_candidate.table_id,
        (SELECT s.seat_number FROM public.table_seats s
          WHERE s.id=v_candidate.seat_id));
      v_table_id:=(v_choice->>'table_id')::uuid;
      v_seat_number:=(v_choice->>'seat_number')::integer;
    END IF;

    UPDATE public.tournament_knockout_candidates c
       SET state='rebought',resolved_at=clock_timestamp()
     WHERE c.id=v_candidate.id AND c.state=v_candidate.state
       AND c.state IN ('pending','eliminated');
    GET DIAGNOSTICS v_rows=ROW_COUNT;
    IF v_rows<>1 THEN
      RAISE EXCEPTION 'exact knockout generation did not close with its purchase'
        USING ERRCODE='40001';
    END IF;
    UPDATE public.tournament_players tp
       SET rebuy_prompt_until=NULL
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;

    -- An old-pod zero seat can still be live during the rolling window. The
    -- money core fills that locked chair; advancing joined_at begins the new
    -- paid entry generation so a later same-chair bust has a new identity. A
    -- new paid generation is also playable state: clear only lifecycle flags
    -- owned by the expired generation while preserving this player's persisted
    -- time bank and auto-rebuy preference. Naming user_id deliberately reruns
    -- the canonical horse and club stamp triggers for the same occupant.
    IF v_live_count=1 THEN
      v_expected_club_id:=public.fn_seat_club_for_user(
        p_user_id,v_live.table_id,v_player.club_id);
      SELECT CASE WHEN COALESCE(p.is_horse,false) THEN p.id ELSE NULL END
        INTO v_expected_horse_id
        FROM public.profiles p
       WHERE p.id=p_user_id;
      UPDATE public.table_seats s
         SET user_id=p_user_id,player_id=NULL,member_id=NULL,
             joined_at=clock_timestamp(),status='active',
             is_sitting_out=false,is_away=false,leave_pending=false,
             sit_out_at=NULL,scheduled_leave_hands=NULL,
             horse_id=v_expected_horse_id,club_id=v_expected_club_id,
             entry_hold=NULL,entry_post_agreed=false
       WHERE s.id=v_live.id AND s.left_at IS NULL
         AND s.user_id=p_user_id
         AND s.joined_at=v_candidate.seat_joined_at;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      IF v_rows<>1 THEN
        RAISE EXCEPTION 'rebuy could not advance the live seat generation'
          USING ERRCODE='40001';
      END IF;
    END IF;

    v_assignment:=public.fn_ca_assign_tournament_player_seat_locked(
      p_tournament_id,p_user_id,v_table_id,v_seat_number);
    IF COALESCE((v_assignment->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'paid rebuy could not commit its chosen seat: %',
        COALESCE(v_assignment->>'reason','unknown') USING ERRCODE='55000';
    END IF;

    PERFORM s.id
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL
     ORDER BY s.id FOR UPDATE OF s;
    SELECT count(*)::integer INTO v_live_count
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL;
    SELECT s.* INTO v_final_seat
      FROM public.table_seats s JOIN public.tables tb ON tb.id=s.table_id
     WHERE tb.tournament_id=p_tournament_id AND s.user_id=p_user_id
       AND s.left_at IS NULL;
    SELECT * INTO v_player FROM public.tournament_players tp
     WHERE tp.tournament_id=p_tournament_id AND tp.user_id=p_user_id;
    v_expected_club_id:=public.fn_seat_club_for_user(
      p_user_id,v_final_seat.table_id,v_player.club_id);
    SELECT CASE WHEN COALESCE(p.is_horse,false) THEN p.id ELSE NULL END
      INTO v_expected_horse_id
      FROM public.profiles p
     WHERE p.id=p_user_id;
    IF v_live_count<>1 OR v_final_seat.id IS NULL
       OR v_final_seat.stack IS NULL OR v_final_seat.stack<=0
       OR v_final_seat.stack<>trunc(v_final_seat.stack)
       OR v_final_seat.stack IS DISTINCT FROM v_player.chips::numeric
       OR v_final_seat.status::text<>'active'
       OR COALESCE(v_final_seat.is_sitting_out,false)
       OR COALESCE(v_final_seat.is_away,false)
       OR COALESCE(v_final_seat.leave_pending,false)
       OR v_final_seat.sit_out_at IS NOT NULL
       OR v_final_seat.scheduled_leave_hands IS NOT NULL
       OR v_final_seat.entry_hold IS NOT NULL
       OR v_final_seat.entry_post_agreed
       OR v_final_seat.player_id IS NOT NULL
       OR v_final_seat.member_id IS NOT NULL
       OR v_final_seat.horse_id IS DISTINCT FROM v_expected_horse_id
       OR v_final_seat.club_id IS DISTINCT FROM v_expected_club_id
       OR v_player.status::text<>'playing'
       OR v_player.table_id IS DISTINCT FROM v_final_seat.table_id
       OR v_player.seat_number IS DISTINCT FROM v_final_seat.seat_number
       OR ((COALESCE(v_t.is_bounty,false) OR COALESCE(v_t.is_pko,false)
            OR COALESCE(v_t.is_mystery_bounty,false)) AND (
         v_bounty_obligation_id IS NULL
         OR round(COALESCE(v_player.current_bounty,0),2) IS DISTINCT FROM
              round(COALESCE((v_response->>'bounty_head_funded')::numeric,0),2)
         OR NOT EXISTS (
           SELECT 1 FROM public.tournament_bounty_obligations o
            WHERE o.id=v_bounty_obligation_id AND o.state='settled'
              AND public.fn_bounty_obligation_has_complete_marker(o.id))))
       OR NOT EXISTS (
         SELECT 1 FROM public.tournament_knockout_candidates c
          WHERE c.id=v_candidate.id AND c.state='rebought')
       OR EXISTS (
         SELECT 1 FROM public.tournament_knockout_candidates c
          WHERE c.tournament_id=p_tournament_id
            AND c.eliminated_user_id=p_user_id AND c.state='pending')
       OR NOT EXISTS (
         SELECT 1 FROM public.tables tb
          WHERE tb.id=v_final_seat.table_id
            AND tb.current_players=(
              SELECT count(*) FROM public.table_seats s
               WHERE s.table_id=tb.id AND s.left_at IS NULL)) THEN
      RAISE EXCEPTION 'atomic rebuy candidate/seat/roster proof is not exact'
        USING ERRCODE='P0404';
    END IF;
    v_wake_id:=public.fn_emit_tournament_manager_wake(p_tournament_id,v_type);
    v_response:=v_response||jsonb_build_object(
      'success',true,'seated',true,'atomic_tournament_chip_purchase','v1',
      'rebuy_type',v_type,'candidate_id',v_candidate.id,
      'candidate_state','rebought','seat_id',v_final_seat.id,
      'table_id',v_final_seat.table_id,
      'seat_number',v_final_seat.seat_number,'stack',v_final_seat.stack,
      'prior_bounty_obligation_id',v_bounty_obligation_id,
      'prior_bounty_marker_verified',
        CASE WHEN v_bounty_obligation_id IS NULL THEN NULL ELSE true END,
      'manager_wake_id',v_wake_id);
  END IF;

  v_recorded:=public.fn_record_entry_purchase_receipt(
    'tournament_chip_purchase',v_receipt_key,v_request,v_response);
  IF v_recorded IS DISTINCT FROM v_response THEN
    RAISE EXCEPTION 'atomic tournament chip-purchase receipt changed at commit'
      USING ERRCODE='P0404';
  END IF;
  PERFORM set_config(
    'app.money_path',COALESCE(v_previous_money_path,''),true);
  RETURN v_recorded;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config(
    'app.money_path',COALESCE(v_previous_money_path,''),true);
  RAISE;
END;
$function$;
