GRANT EXECUTE ON FUNCTION public.process_tournament_rebuy(uuid,uuid,text,numeric,numeric,integer,text) TO "postgres";
GRANT EXECUTE ON FUNCTION public.process_tournament_rebuy(uuid,uuid,text,numeric,numeric,integer,text) TO "authenticated";
GRANT EXECUTE ON FUNCTION public.process_tournament_rebuy(uuid,uuid,text,numeric,numeric,integer,text) TO "service_role";
DO $absent$ BEGIN IF to_regprocedure('public.fn_ca_assert_tournament_chip_grant(uuid,uuid,uuid,numeric,text)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_ca_assert_tournament_chip_grant(uuid,uuid,uuid,numeric,text)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_ca_assert_tournament_chip_grant(p_tournament_id uuid, p_user_id uuid, p_seat_id uuid, p_new_stack numeric, p_source text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_felt numeric;
  v_own numeric;
  v_supply numeric;
  v_after numeric;
BEGIN
  IF p_tournament_id IS NULL OR p_new_stack IS NULL THEN
    RAISE EXCEPTION 'tournament chip grant assertion needs a tournament and a stack'
      USING ERRCODE='22023';
  END IF;
  IF p_new_stack::text IN ('NaN','Infinity','-Infinity') OR p_new_stack<0 THEN
    RAISE EXCEPTION 'TOURNAMENT_CHIP_GRANT_INVALID: % proposed stack %',
      COALESCE(p_source,'grant'),p_new_stack
      USING ERRCODE='22023';
  END IF;

  v_supply:=public.fn_ca_tournament_chip_supply(p_tournament_id);
  v_felt:=public.fn_ca_tournament_felt_total(p_tournament_id);
  SELECT COALESCE(ts.stack,0) INTO v_own
    FROM public.table_seats ts
   WHERE ts.id=p_seat_id AND ts.left_at IS NULL;
  v_after:=v_felt-COALESCE(v_own,0)+p_new_stack;

  IF v_after>v_felt AND v_after>v_supply THEN
    RAISE EXCEPTION
      'TOURNAMENT_CHIP_GRANT_WOULD_MINT: % for player % would leave % chips on the felt in tournament % against % ever bought in (felt now %, this seat holds %) - Aborting So No Charge Is Made',
      COALESCE(p_source,'grant'),p_user_id,v_after,p_tournament_id,v_supply,
      v_felt,COALESCE(v_own,0)
      USING ERRCODE='55000';
  END IF;
END;
$function$;
ALTER FUNCTION public.fn_ca_assert_tournament_chip_grant(uuid,uuid,uuid,numeric,text) OWNER TO "postgres";
REVOKE ALL ON FUNCTION public.fn_ca_assert_tournament_chip_grant(uuid,uuid,uuid,numeric,text) FROM PUBLIC,"anon","authenticated","postgres","service_role";
GRANT EXECUTE ON FUNCTION public.fn_ca_assert_tournament_chip_grant(uuid,uuid,uuid,numeric,text) TO "postgres";
GRANT EXECUTE ON FUNCTION public.fn_ca_assert_tournament_chip_grant(uuid,uuid,uuid,numeric,text) TO "service_role";
DO $absent$ BEGIN IF to_regprocedure('public.fn_collect_bounty_obligation(uuid)') IS NOT NULL THEN RAISE EXCEPTION 'R46 supplement already exists: %','public.fn_collect_bounty_obligation(uuid)'; END IF; END $absent$;
CREATE OR REPLACE FUNCTION public.fn_collect_bounty_obligation(p_obligation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  o public.tournament_bounty_obligations%ROWTYPE;
  v_prior_context text := current_setting('app.bounty_obligation_id',true);
  v_result jsonb;
BEGIN
  SELECT * INTO o FROM public.tournament_bounty_obligations WHERE id=p_obligation_id;
  IF NOT FOUND OR o.mode='mystery_chest' THEN
    RETURN jsonb_build_object('ok',false,'reason','bounty_obligation_not_found');
  END IF;
  PERFORM set_config('app.bounty_obligation_id',o.id::text,true);
  v_result := public.fn_collect_bounty(
    o.tournament_id,o.eliminated_user_id,o.knocker_user_id,o.claimants);
  PERFORM set_config('app.bounty_obligation_id',COALESCE(v_prior_context,''),true);
  RETURN v_result;
END;
$function$;
