DECLARE catalog jsonb := '{"functions":[{"identity":"public.atomic_cancel_tournament(p_tournament_id uuid, p_admin_id uuid)","source_md5":"f099ff40e1bc071dd90de91ea36e6dbd","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"},{"role":"service_role","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"6dac23baee41ff69ee0e1243f0a26c8e","identity_kind":"named_arguments"},{"identity":"public.fn_settle_tournament_rake(p_tournament_id uuid, p_source text)","source_md5":"0e7baa1bfeb2a2d0fed749a52f32d520","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"},{"role":"service_role","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"7cf1d81246d015b65d416ee6b3f96838","identity_kind":"named_arguments"},{"identity":"public.fn_settle_tournament_obligation(p_tournament_id uuid, p_kind text, p_place integer, p_user_id uuid, p_amount numeric, p_source text, p_description text, p_adjustment_id uuid)","source_md5":"915f3ebd5c4a2efb97ad3a354dfeb365","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"},{"role":"service_role","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"5a881321824161ae69c1c623982d4a29","identity_kind":"named_arguments"},{"identity":"public.fn_settle_tournament_places(p_tournament_id uuid, p_observed_winner_id uuid)","source_md5":"6181734ff98555ecc04648186f6ebf24","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"},{"role":"service_role","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"c412c8b17186976df139f73a706175f2","identity_kind":"named_arguments"},{"identity":"public.fn_ca_satellite_settlement_receipt(p_tournament_id uuid, p_observed_winner_id uuid)","source_md5":"381b3e0691a2b9303693653f5110d568","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"706ce8ee53b87a2a5547443b460ceb93","identity_kind":"named_arguments"},{"identity":"public.fn_settle_satellite_tournament_pre_money_path_gate(p_tournament_id uuid, p_observed_winner_id uuid)","source_md5":"83bf8b297d07bbae671707f24afec271","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"b36386009f2b3f568fc648efbccaf7b4","identity_kind":"named_arguments"},{"identity":"public.fn_ca_tournament_cancellation_receipt(p_tournament_id uuid, p_observed_actor_id uuid)","source_md5":"17abfb4379f0b526839fb09270369bd7","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"cf0bf7f56e2e50376626c37b59cfaca8","identity_kind":"named_arguments"},{"identity":"public.fn_stamp_tournament_terminal_evidence_markers()","source_md5":"da7d45473b1c4422fde12c2c234dddeb","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"eeec4e4610901fe4b44b0b8f270d1ef7","identity_kind":"named_arguments"},{"identity":"public.fn_ca_tournament_terminal_receipt(p_tournament_id uuid, p_observed_winner_id uuid)","source_md5":"1299bd56c938864f55c9e53206bc76df","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"317b582f72d120c745a5b7073d9b559a","identity_kind":"named_arguments"},{"identity":"public.fn_complete_tournament_terminal_pre_seat_guard(p_tournament_id uuid, p_observed_winner_id uuid, p_settlement_mode text)","source_md5":"15de38b6e3cf35e21621b240a7a6f51e","owner":"postgres","grants":[{"role":"postgres","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"062c9a1314f33a5c8af4fdf5e00a046d","identity_kind":"named_arguments"},{"identity":"auth.uid()","source_md5":"cdef18c69c4f4cbbced2eaf81e628b49","owner":"supabase_auth_admin","grants":[{"role":"PUBLIC","grantable":false,"privilege":"EXECUTE"},{"role":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"},{"role":"dashboard_user","grantable":false,"privilege":"EXECUTE"}],"definition_md5":"ea3b41bf29e2ad573